import type { AuditEventRecord } from "./audit-history";
import type { CompletedServiceRecord, PersistedPlanningSet } from "./planning-lifecycle";

type PlanningAttributionInput = {
  activeSets: PersistedPlanningSet[];
  completedRecords: CompletedServiceRecord[];
  events: AuditEventRecord[];
};

type BusinessState = {
  serviceContext: unknown;
  language: unknown;
  rows: unknown[];
};

class UnionFind {
  private readonly parent = new Map<string, string>();

  add(value: string) {
    if (!this.parent.has(value)) this.parent.set(value, value);
  }

  find(value: string): string {
    this.add(value);
    const parent = this.parent.get(value)!;
    if (parent === value) return value;
    const root = this.find(parent);
    this.parent.set(value, root);
    return root;
  }

  union(left: string, right: string) {
    const leftRoot = this.find(left);
    const rightRoot = this.find(right);
    if (leftRoot !== rightRoot) this.parent.set(rightRoot, leftRoot);
  }
}

export function attributePlanningLastEditors(input: PlanningAttributionInput) {
  const unionFind = new UnionFind();

  for (const set of input.activeSets) unionFind.add(entityKey("planningSet", set.id));
  for (const record of input.completedRecords) unionFind.add(entityKey("completedService", record.id));

  for (const event of input.events) connectEventLineage(unionFind, event);

  const lastChangedByRoot = new Map<string, string>();
  const orderedEvents = [...input.events].sort((left, right) =>
    left.occurredAt.getTime() - right.occurredAt.getTime() || left.id - right.id,
  );

  for (const event of orderedEvents) {
    if (event.actorKind !== "human" || !event.actorDisplayName?.trim()) continue;
    if (!businessContentChanged(event.beforeState, event.afterState)) continue;

    const key = auditObjectKey(event);
    if (!key) continue;
    lastChangedByRoot.set(unionFind.find(key), event.actorDisplayName.trim());
  }

  return {
    activeSets: input.activeSets.map((set) => {
      const lastChangedBy = lastChangedByRoot.get(unionFind.find(entityKey("planningSet", set.id)));
      return lastChangedBy ? { ...set, lastChangedBy } : { ...set };
    }),
    completedRecords: input.completedRecords.map((record) => {
      const lastChangedBy = lastChangedByRoot.get(unionFind.find(entityKey("completedService", record.id)));
      return lastChangedBy ? { ...record, lastChangedBy } : { ...record };
    }),
  };
}

export function businessContentChanged(beforeState: unknown, afterState: unknown): boolean {
  const before = extractBusinessState(beforeState);
  const after = extractBusinessState(afterState);
  if (!before && !after) return false;
  if (!before || !after) return true;
  return stableStringify(before) !== stableStringify(after);
}

export function shouldRecordPlanningAudit(action: string, beforeState: unknown, afterState: unknown): boolean {
  if (action === "saveWorkingSet" || action === "updateCompletedRecord") {
    return businessContentChanged(beforeState, afterState);
  }
  return true;
}

function connectEventLineage(unionFind: UnionFind, event: AuditEventRecord) {
  const objectKey = auditObjectKey(event);
  if (!objectKey) return;
  unionFind.add(objectKey);

  if (event.objectKind === "planningSet") {
    for (const id of [readString(event.beforeState, "id"), readString(event.afterState, "id")]) {
      if (id) unionFind.union(objectKey, entityKey("planningSet", id));
    }
    return;
  }

  if (event.objectKind !== "completedService") return;

  if (event.action === "planning.final.complete" || event.action === "planning.final.autoComplete") {
    const sourceFinalSetId =
      readString(event.beforeState, "sourceFinalSetId")
      ?? readString(event.beforeState, "id")
      ?? readString(event.afterState, "sourceFinalSetId");
    if (sourceFinalSetId) unionFind.union(objectKey, entityKey("planningSet", sourceFinalSetId));
    const completedId = readString(event.afterState, "id");
    if (completedId) unionFind.union(objectKey, entityKey("completedService", completedId));
    return;
  }

  if (event.action.startsWith("planning.completed.")) {
    for (const id of [readString(event.beforeState, "id"), readString(event.afterState, "id")]) {
      if (id) unionFind.union(objectKey, entityKey("completedService", id));
    }
  }
}

function auditObjectKey(event: AuditEventRecord): string | undefined {
  if (event.objectKind !== "planningSet" && event.objectKind !== "completedService") return undefined;
  return entityKey(event.objectKind, event.objectRef);
}

function entityKey(kind: "planningSet" | "completedService", id: string): string {
  return `${kind}:${id}`;
}

function extractBusinessState(value: unknown): BusinessState | undefined {
  if (!isRecord(value) || !isRecord(value.serviceContext)) return undefined;

  const nestedSet = isRecord(value.set) ? value.set : undefined;
  const rows = Array.isArray(value.rows) ? value.rows : nestedSet && Array.isArray(nestedSet.rows) ? nestedSet.rows : undefined;
  if (!rows) return undefined;

  const language =
    typeof value.language === "string"
      ? value.language
      : nestedSet && typeof nestedSet.language === "string"
        ? nestedSet.language
        : value.serviceContext.language;

  return {
    serviceContext: value.serviceContext,
    language,
    rows,
  };
}

function readString(value: unknown, key: string): string | undefined {
  if (!isRecord(value)) return undefined;
  const candidate = value[key];
  return typeof candidate === "string" && candidate ? candidate : undefined;
}

function stableStringify(value: unknown): string {
  return JSON.stringify(sortValue(value));
}

function sortValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortValue);
  if (!isRecord(value)) return value;
  return Object.fromEntries(Object.keys(value).sort().map((key) => [key, sortValue(value[key])]));
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

import { asc, eq, sql } from "drizzle-orm";
import type { NodePgDatabase } from "drizzle-orm/node-postgres";
import type * as planningLifecycleSchema from "../../db/schema";
import {
  completedServiceRows,
  completedServices,
  serviceContexts,
  serviceSetRows,
  serviceSets,
  melodyNonRepetitionConfig,
} from "../../db/schema";
import type {
  CompletedServiceRecord,
  CompletedServiceRecordRepository,
  FinalSetCompletionPersistenceResult,
  FinalSetCompletionRepository,
  PersistedPlanningPlan,
  PlanningPlanId,
  PlanningPlanRepository,
} from "./ports";
import { PlanningLifecycleService } from "./service";
import { DrizzleCatalogRepository } from "../catalog";
import type { PlanningLifecycleServiceDependencies } from "./service";
import { normalizeServiceTime, type PlanningRow, type PlanningPlan, type ServiceContext, type ServiceLanguage } from "../../planning-lifecycle";

export type PlanningLifecycleDrizzleSchema = Pick<
  typeof planningLifecycleSchema,
  | "serviceContexts"
  | "serviceSets"
  | "serviceSetRows"
  | "completedServices"
  | "completedServiceRows"
>;

type PlanningLifecycleDrizzleDatabase = NodePgDatabase<typeof planningLifecycleSchema>;
type DrizzleExecutor = Pick<PlanningLifecycleDrizzleDatabase, "select" | "insert" | "update" | "delete">;
type DrizzleTable = Parameters<PlanningLifecycleDrizzleDatabase["insert"]>[0];

export type PlanningLifecycleDrizzleAdapterDependencies = {
  db: PlanningLifecycleDrizzleDatabase;
  schema?: PlanningLifecycleDrizzleSchema;
};

type ServiceSetRecord = {
  id: number;
  serviceContextId: number;
  status: "working" | "final";
};

type ServiceContextRecord = {
  id: number;
  serviceDate: string;
  serviceTime: string | null;
  serviceLanguage: ServiceLanguage;
  priestId: string | null;
  priestDisplayName: string;
  organistId: string | null;
  organistDisplayName: string;
  note: string | null;
  referenceAntiphonId: string | null;
  referenceAntiphonDisplayNumber: string | null;
  referenceAntiphonTitle: string | null;
  referenceAntiphonSourceUrl: string | null;
  referenceTopicId: string | null;
  referenceTopicTitle: string | null;
  antiphonKey: string | null;
  liturgicalSeasonKey: string | null;
};

type ServiceSetRowRecord = {
  position: number;
  songLanguage: "czech" | "polish" | null;
  songId: string | null;
  songNumber: string | null;
  songTitle: string | null;
  note: string | null;
};

type CompletedServiceRecordRecord = {
  id: number;
  serviceSetId: number | null;
  serviceContextId: number;
  completedAt: Date;
};

export class DrizzlePlanningSetRepository implements PlanningPlanRepository {
  constructor(private readonly dependencies: PlanningLifecycleDrizzleAdapterDependencies) {}

  async list(): Promise<PersistedPlanningPlan[]> {
    const sets = (await selectAll(this.dependencies.db).from(serviceSets).orderBy(asc(serviceSets.id))) as ServiceSetRecord[];
    const loaded = await Promise.all(sets.map((set) => this.findByIdWithExecutor(this.dependencies.db, set.id)));
    return loaded.filter((set): set is PersistedPlanningPlan => Boolean(set));
  }

  async findById(id: PlanningPlanId): Promise<PersistedPlanningPlan | undefined> {
    const numericId = parsePlanningSetId(id);
    if (numericId === undefined) {
      return undefined;
    }

    const db = this.dependencies.db;
    const [set] = (await selectAll(db)
      .from(serviceSets)
      .where(eq(serviceSets.id, numericId))
      .limit(1)) as ServiceSetRecord[];

    if (!set) {
      return undefined;
    }

    const [context] = (await selectAll(db)
      .from(serviceContexts)
      .where(eq(serviceContexts.id, set.serviceContextId))
      .limit(1)) as ServiceContextRecord[];

    if (!context) {
      return undefined;
    }

    const rows = (await selectAll(db)
      .from(serviceSetRows)
      .where(eq(serviceSetRows.serviceSetId, set.id))
      .orderBy(asc(serviceSetRows.position))) as ServiceSetRowRecord[];

    return {
      id: formatPlanningSetId(set.id),
      status: set.status,
      language: context.serviceLanguage,
      serviceContext: mapContextRecordToServiceContext(context),
      rows: rows.map(mapRowRecordToPlanningRow),
    };
  }

  async saveWorkingSet(
    set: PlanningPlan & { status: "working" },
    serviceContext: ServiceContext,
    existingId?: PlanningPlanId,
  ): Promise<PersistedPlanningPlan> {
    return this.saveSet(set, serviceContext, existingId);
  }

  async saveFinalSet(
    set: PlanningPlan & { status: "final" },
    serviceContext: ServiceContext,
    existingId?: PlanningPlanId,
  ): Promise<PersistedPlanningPlan> {
    return this.saveSet(set, serviceContext, existingId);
  }

  async demoteFinalToWorking(id: PlanningPlanId): Promise<void> {
    const numericId = parsePlanningSetId(id);
    if (numericId === undefined) return;
    await updateTable(this.dependencies.db, serviceSets)
      .set({ status: "working", updatedAt: new Date() })
      .where(eq(serviceSets.id, numericId));
  }

  async deleteById(id: PlanningPlanId): Promise<void> {
    const numericId = parsePlanningSetId(id);
    if (numericId === undefined) {
      return;
    }

    await this.dependencies.db.transaction(async (tx) => {
      const [set] = (await selectAll(tx)
        .from(serviceSets)
        .where(eq(serviceSets.id, numericId))
        .limit(1)) as ServiceSetRecord[];

      if (!set) {
        return;
      }

      const serviceContextId = set.serviceContextId;
      await deleteFrom(tx, serviceSets).where(eq(serviceSets.id, numericId));

      const completedReferencingContext = (await selectAll(tx)
        .from(completedServices)
        .where(eq(completedServices.serviceContextId, serviceContextId))
        .limit(1)) as CompletedServiceRecordRecord[];

      if (completedReferencingContext.length === 0) {
        await deleteFrom(tx, serviceContexts).where(eq(serviceContexts.id, serviceContextId));
      }
    });
  }

  private async saveSet<TSet extends PlanningPlan>(set: TSet, serviceContext: ServiceContext, existingId?: PlanningPlanId): Promise<PersistedPlanningPlan> {
    return this.dependencies.db.transaction(async (tx) => {
      const now = new Date();
      const existingNumericId = existingId ? parsePlanningSetId(existingId) : undefined;

      if (existingId && existingNumericId === undefined) {
        throw new Error(`Planning set id '${existingId}' is not a valid database-backed planning set id.`);
      }

      const serviceSetId = existingNumericId
        ? await updateExistingSet(tx, existingNumericId, set, serviceContext, now)
        : await insertNewSet(tx, set, serviceContext, now);

      await replaceRows(tx, serviceSetId, set.rows, now);

      const persisted = await this.findByIdWithExecutor(tx, serviceSetId);
      if (!persisted) {
        throw new Error(`Planning set '${serviceSetId}' was not found after save.`);
      }

      return persisted;
    });
  }

  private async findByIdWithExecutor(db: DrizzleExecutor, numericId: number): Promise<PersistedPlanningPlan | undefined> {
    const [set] = (await selectAll(db)
      .from(serviceSets)
      .where(eq(serviceSets.id, numericId))
      .limit(1)) as ServiceSetRecord[];

    if (!set) {
      return undefined;
    }

    const [context] = (await selectAll(db)
      .from(serviceContexts)
      .where(eq(serviceContexts.id, set.serviceContextId))
      .limit(1)) as ServiceContextRecord[];

    if (!context) {
      return undefined;
    }

    const rows = (await selectAll(db)
      .from(serviceSetRows)
      .where(eq(serviceSetRows.serviceSetId, set.id))
      .orderBy(asc(serviceSetRows.position))) as ServiceSetRowRecord[];

    return {
      id: formatPlanningSetId(set.id),
      status: set.status,
      language: context.serviceLanguage,
      serviceContext: mapContextRecordToServiceContext(context),
      rows: rows.map(mapRowRecordToPlanningRow),
    };
  }
}

export class DrizzleFinalSetCompletionRepository implements FinalSetCompletionRepository {
  constructor(private readonly dependencies: PlanningLifecycleDrizzleAdapterDependencies) {}

  async completeFinalSet(finalSetId: PlanningPlanId, completedAt: Date): Promise<FinalSetCompletionPersistenceResult> {
    const numericId = parsePlanningSetId(finalSetId);
    if (numericId === undefined) return { status: "notFound" };

    return this.dependencies.db.transaction(async (tx) => {
      // Serialize concurrent automatic/manual completion attempts for the same Final row.
      await tx.execute(sql`select ${serviceSets.id} from ${serviceSets} where ${serviceSets.id} = ${numericId} for update`);

      const [sourceFinalSet] = (await selectAll(tx)
        .from(serviceSets)
        .where(eq(serviceSets.id, numericId))
        .limit(1)) as ServiceSetRecord[];
      if (!sourceFinalSet) return { status: "notFound" };
      if (sourceFinalSet.status !== "final") return { status: "notFinal" };

      const [context] = (await selectAll(tx)
        .from(serviceContexts)
        .where(eq(serviceContexts.id, sourceFinalSet.serviceContextId))
        .limit(1)) as ServiceContextRecord[];
      if (!context) throw new Error(`Service context for final set '${finalSetId}' was not found.`);

      const rows = (await selectAll(tx)
        .from(serviceSetRows)
        .where(eq(serviceSetRows.serviceSetId, numericId))
        .orderBy(asc(serviceSetRows.position))) as ServiceSetRowRecord[];
      const planningRows = rows.map(mapRowRecordToPlanningRow);
      const now = new Date();

      const [completedService] = (await insertInto(tx, completedServices)
        .values({
          serviceContextId: sourceFinalSet.serviceContextId,
          serviceSetId: numericId,
          completedAt,
          createdAt: now,
          updatedAt: now,
        })
        .returning({
          id: completedServices.id,
          serviceSetId: completedServices.serviceSetId,
          serviceContextId: completedServices.serviceContextId,
          completedAt: completedServices.completedAt,
        })) as CompletedServiceRecordRecord[];

      if (planningRows.length > 0) {
        await insertInto(tx, completedServiceRows).values(
          planningRows.map((row, index) => ({
            completedServiceId: completedService.id,
            position: index + 1,
            songId: row.song?.songId,
            songLanguage: row.song?.language,
            songNumber: row.song?.number,
            songTitle: row.song?.title,
            note: row.note,
            createdAt: now,
            updatedAt: now,
          })),
        );
      }

      // Same transaction: FK changes completed_services.service_set_id to null,
      // service_set_rows cascade away, while service_context survives via Completed.
      await deleteFrom(tx, serviceSets).where(eq(serviceSets.id, numericId));

      return {
        status: "completed",
        record: {
          id: formatCompletedServiceRecordId(completedService.id),
          sourceFinalSetId: finalSetId,
          set: { status: "final", language: context.serviceLanguage, rows: planningRows },
          serviceContext: mapContextRecordToServiceContext(context),
          completedAt: new Date(completedService.completedAt),
        },
      };
    });
  }
}

export class DrizzleCompletedServiceRecordRepository implements CompletedServiceRecordRepository {
  constructor(private readonly dependencies: PlanningLifecycleDrizzleAdapterDependencies) {}

  async createFromFinalSet(record: Omit<CompletedServiceRecord, "id">): Promise<CompletedServiceRecord> {
    const sourceFinalSetNumericId = parsePlanningSetId(record.sourceFinalSetId);
    if (sourceFinalSetNumericId === undefined) {
      throw new Error(
        `Source final set id '${record.sourceFinalSetId}' is not a valid database-backed planning set id.`,
      );
    }

    return this.dependencies.db.transaction(async (tx) => {
      const now = new Date();
      const [sourceFinalSet] = (await selectAll(tx)
        .from(serviceSets)
        .where(eq(serviceSets.id, sourceFinalSetNumericId))
        .limit(1)) as ServiceSetRecord[];

      if (!sourceFinalSet) {
        throw new Error(`Source final set '${record.sourceFinalSetId}' was not found.`);
      }

      if (sourceFinalSet.status !== "final") {
        throw new Error(`Source planning set '${record.sourceFinalSetId}' is not final.`);
      }

      const [completedService] = (await insertInto(tx, completedServices)
        .values({
          serviceContextId: sourceFinalSet.serviceContextId,
          serviceSetId: sourceFinalSetNumericId,
          completedAt: record.completedAt,
          createdAt: now,
          updatedAt: now,
        })
        .returning({
          id: completedServices.id,
          serviceSetId: completedServices.serviceSetId,
          serviceContextId: completedServices.serviceContextId,
          completedAt: completedServices.completedAt,
        })) as CompletedServiceRecordRecord[];

      if (record.set.rows.length > 0) {
        await insertInto(tx, completedServiceRows).values(
          record.set.rows.map((row, index) => ({
            completedServiceId: completedService.id,
            position: index + 1,
            songId: row.song?.songId,
            songLanguage: row.song?.language,
            songNumber: row.song?.number,
            songTitle: row.song?.title,
            note: row.note,
            createdAt: now,
            updatedAt: now,
          })),
        );
      }

      return {
        id: formatCompletedServiceRecordId(completedService.id),
        sourceFinalSetId: record.sourceFinalSetId,
        set: clonePlanningSet(record.set),
        serviceContext: record.serviceContext,
        completedAt: new Date(completedService.completedAt),
      };
    });
  }

  async list(): Promise<CompletedServiceRecord[]> {
    const rows = (await selectAll(this.dependencies.db).from(completedServices).orderBy(asc(completedServices.id))) as CompletedServiceRecordRecord[];
    return Promise.all(rows.map((row) => this.hydrate(row)));
  }

  async findById(id: string): Promise<CompletedServiceRecord | undefined> {
    const numericId = parsePlanningSetId(id);
    if (numericId === undefined) return undefined;
    const [row] = (await selectAll(this.dependencies.db).from(completedServices).where(eq(completedServices.id, numericId)).limit(1)) as CompletedServiceRecordRecord[];
    return row ? this.hydrate(row) : undefined;
  }

  private async hydrate(row: CompletedServiceRecordRecord): Promise<CompletedServiceRecord> {
    return this.hydrateWithExecutor(this.dependencies.db, row);
  }

  private async hydrateWithExecutor(db: DrizzleExecutor, row: CompletedServiceRecordRecord): Promise<CompletedServiceRecord> {
    const [context] = (await selectAll(db).from(serviceContexts).where(eq(serviceContexts.id, row.serviceContextId)).limit(1)) as ServiceContextRecord[];
    const rows = (await selectAll(db).from(completedServiceRows).where(eq(completedServiceRows.completedServiceId, row.id)).orderBy(asc(completedServiceRows.position))) as ServiceSetRowRecord[];
    return { id: formatCompletedServiceRecordId(row.id), sourceFinalSetId: row.serviceSetId ? formatPlanningSetId(row.serviceSetId) : "", set: { status: "final", language: context.serviceLanguage, rows: rows.map(mapRowRecordToPlanningRow) }, serviceContext: mapContextRecordToServiceContext(context), completedAt: new Date(row.completedAt) };
  }

  async update(id: string, serviceContext: ServiceContext, set: PlanningPlan & { status: "final" }, invalidatedPlanIds: PlanningPlanId[] = []): Promise<CompletedServiceRecord> {
    const numericId = parsePlanningSetId(id);
    if (numericId === undefined) {
      throw new Error(`Completed service record id '${id}' is not valid.`);
    }

    return this.dependencies.db.transaction(async (tx) => {
      const now = new Date();
      const [existing] = (await selectAll(tx).from(completedServices).where(eq(completedServices.id, numericId)).limit(1)) as CompletedServiceRecordRecord[];
      if (!existing) {
        throw new Error(`Completed service record '${id}' was not found.`);
      }

      await updateTable(tx, serviceContexts)
        .set({ ...mapServiceContextToContextValues(serviceContext), serviceLanguage: set.language, updatedAt: now })
        .where(eq(serviceContexts.id, existing.serviceContextId));
      await updateTable(tx, completedServices).set({ updatedAt: now }).where(eq(completedServices.id, numericId));
      await replaceCompletedRows(tx, numericId, set.rows, now);
      for (const planId of invalidatedPlanIds) {
        const planNumericId = parsePlanningSetId(planId);
        if (planNumericId !== undefined) await updateTable(tx, serviceSets).set({ status: "working", updatedAt: now }).where(eq(serviceSets.id, planNumericId));
      }
      const [updated] = (await selectAll(tx).from(completedServices).where(eq(completedServices.id, numericId)).limit(1)) as CompletedServiceRecordRecord[];
      return this.hydrateWithExecutor(tx, updated);
    });
  }

  async deleteById(id: string): Promise<void> {
    const numericId = parsePlanningSetId(id);
    if (numericId === undefined) return;

    await this.dependencies.db.transaction(async (tx) => {
      const [existing] = (await selectAll(tx).from(completedServices).where(eq(completedServices.id, numericId)).limit(1)) as CompletedServiceRecordRecord[];
      if (!existing) return;
      const serviceContextId = existing.serviceContextId;
      await deleteFrom(tx, completedServices).where(eq(completedServices.id, numericId));

      const activeReferencingContext = (await selectAll(tx).from(serviceSets).where(eq(serviceSets.serviceContextId, serviceContextId)).limit(1)) as ServiceSetRecord[];
      const completedReferencingContext = (await selectAll(tx).from(completedServices).where(eq(completedServices.serviceContextId, serviceContextId)).limit(1)) as CompletedServiceRecordRecord[];
      if (activeReferencingContext.length === 0 && completedReferencingContext.length === 0) {
        await deleteFrom(tx, serviceContexts).where(eq(serviceContexts.id, serviceContextId));
      }
    });
  }

  async deleteBySourceFinalSetId(sourceFinalSetId: PlanningPlanId): Promise<void> {
    const numericId = parsePlanningSetId(sourceFinalSetId);
    if (numericId === undefined) {
      return;
    }

    await deleteFrom(this.dependencies.db, completedServices).where(eq(completedServices.serviceSetId, numericId));
  }
}

export function createDbBackedPlanningLifecycleService(
  dependencies: PlanningLifecycleDrizzleAdapterDependencies & Partial<Pick<PlanningLifecycleServiceDependencies, "now" | "referenceAntiphons" | "referenceTopics" | "referenceSongs" | "referenceMelodyClasses">>,
): PlanningLifecycleService {
  return new PlanningLifecycleService({
    planningSets: new DrizzlePlanningSetRepository(dependencies),
    completedServiceRecords: new DrizzleCompletedServiceRecordRepository(dependencies),
    finalSetCompletion: new DrizzleFinalSetCompletionRepository(dependencies),
    catalog: new DrizzleCatalogRepository(dependencies.db),
    referenceAntiphons: dependencies.referenceAntiphons,
    referenceTopics: dependencies.referenceTopics,
    referenceSongs: dependencies.referenceSongs,
    referenceMelodyClasses: dependencies.referenceMelodyClasses,
    melodyNonRepetitionMonths: async () => {
      const rows = await dependencies.db.select({ months: melodyNonRepetitionConfig.months }).from(melodyNonRepetitionConfig).limit(1);
      return Number(rows[0]?.months ?? 2);
    },
    now: dependencies.now,
  });
}

async function insertNewSet(db: DrizzleExecutor, set: PlanningPlan, serviceContext: ServiceContext, now: Date): Promise<number> {
  const [context] = (await insertInto(db, serviceContexts)
    .values({ ...mapServiceContextToContextValues(serviceContext), serviceLanguage: set.language, createdAt: now, updatedAt: now })
    .returning({ id: serviceContexts.id })) as { id: number }[];

  const [serviceSet] = (await insertInto(db, serviceSets)
    .values({ serviceContextId: context.id, status: set.status, createdAt: now, updatedAt: now })
    .returning({ id: serviceSets.id })) as { id: number }[];

  return serviceSet.id;
}

async function updateExistingSet(db: DrizzleExecutor, id: number, set: PlanningPlan, serviceContext: ServiceContext, now: Date): Promise<number> {
  const [existing] = (await selectAll(db)
    .from(serviceSets)
    .where(eq(serviceSets.id, id))
    .limit(1)) as ServiceSetRecord[];

  if (!existing) {
    throw new Error(`Planning set '${formatPlanningSetId(id)}' was not found.`);
  }

  await updateTable(db, serviceContexts)
    .set({ ...mapServiceContextToContextValues(serviceContext), serviceLanguage: set.language, updatedAt: now })
    .where(eq(serviceContexts.id, existing.serviceContextId));

  await updateTable(db, serviceSets)
    .set({ status: set.status, updatedAt: now })
    .where(eq(serviceSets.id, id));

  return id;
}

async function replaceRows(db: DrizzleExecutor, serviceSetId: number, rows: PlanningRow[], now: Date): Promise<void> {
  await deleteFrom(db, serviceSetRows).where(eq(serviceSetRows.serviceSetId, serviceSetId));

  if (rows.length === 0) {
    return;
  }

  await insertInto(db, serviceSetRows).values(
    rows.map((row, index) => ({
      serviceSetId,
      position: index + 1,
      songId: row.song?.songId,
      songLanguage: row.song?.language,
      songNumber: row.song?.number,
      songTitle: row.song?.title,
      note: row.note,
      createdAt: now,
      updatedAt: now,
    })),
  );
}

async function replaceCompletedRows(db: DrizzleExecutor, completedServiceId: number, rows: PlanningRow[], now: Date): Promise<void> {
  await deleteFrom(db, completedServiceRows).where(eq(completedServiceRows.completedServiceId, completedServiceId));

  if (rows.length === 0) {
    return;
  }

  await insertInto(db, completedServiceRows).values(
    rows.map((row, index) => ({
      completedServiceId,
      position: index + 1,
      songId: row.song?.songId,
      songLanguage: row.song?.language,
      songNumber: row.song?.number,
      songTitle: row.song?.title,
      note: row.note,
      createdAt: now,
      updatedAt: now,
    })),
  );
}

