export class PlanningLifecycleService {
  private readonly now: () => Date;
  private readonly planningSets: PlanningPlanRepository;
  private readonly completedServiceRecords: CompletedServiceRecordRepository;
  private readonly finalSetCompletion?: FinalSetCompletionRepository;
  private fallbackCompletionTail: Promise<void> = Promise.resolve();
  private readonly catalog: CatalogRepository;
  private readonly referenceAntiphons?: Pick<ReferenceAntiphonProvider, "getById">;
  private readonly referenceTopics?: Pick<ReferenceThematicSectionProvider, "getSectionById">;
  private readonly referenceSongs?: { getById(id: string): ReferenceCatalogRecord | undefined | Promise<ReferenceCatalogRecord | undefined> };
  private readonly referenceMelodyClasses?: ReferenceMelodyClassProvider;
  private readonly melodyNonRepetitionMonths: () => Promise<number>;
  private readonly enforceCatalogSelections: boolean;

  constructor(dependencies: PlanningLifecycleServiceDependencies) {
    this.planningSets = dependencies.planningSets;
    this.completedServiceRecords = dependencies.completedServiceRecords;
    this.finalSetCompletion = dependencies.finalSetCompletion;
    this.catalog = dependencies.catalog;
    this.referenceAntiphons = dependencies.referenceAntiphons;
    this.referenceTopics = dependencies.referenceTopics;
    this.referenceSongs = dependencies.referenceSongs;
    this.referenceMelodyClasses = dependencies.referenceMelodyClasses;
    this.melodyNonRepetitionMonths = async () => Number(await dependencies.melodyNonRepetitionMonths?.() ?? 2);
    this.enforceCatalogSelections = dependencies.enforceCatalogSelections ?? true;
    this.now = dependencies.now ?? (() => new Date());
  }


  async listPlanningSets(): Promise<PlanningServiceResult<PersistedPlanningPlan[]>> {
    await this.reconcilePastFinalSets();
    return success(await this.annotateRevisionStates(await this.planningSets.list()));
  }

  async listCompletedRecords(): Promise<PlanningServiceResult<CompletedServiceRecord[]>> {
    await this.reconcilePastFinalSets();
    return success(await this.completedServiceRecords.list());
  }

  async loadPlanningSet(setId: PlanningPlanId): Promise<PlanningServiceResult<PersistedPlanningPlan>> {
    const set = await this.planningSets.findById(setId);
    if (!set) return failure({ code: "notFound", message: "Planning set was not found." });
    return success((await this.annotateRevisionStates([set]))[0]);
  }

  async loadCompletedRecord(recordId: string): Promise<PlanningServiceResult<CompletedServiceRecord>> {
    const record = await this.completedServiceRecords.findById(recordId);
    return record ? success(record) : failure({ code: "notFound", message: "Completed record was not found." });
  }

  async saveWorkingSet(input: SaveWorkingSetInput): Promise<PlanningServiceResult<PersistedPlanningPlan>> {
    if (!canPerformPlanningAction(input.role, input.existingSetId ? "editWorkingSet" : "createWorkingSet")) {
      return failure({ code: "permissionDenied", message: "Role cannot save a working planning set." });
    }

    const rawServiceContext: SaveWorkingSetServiceContext = normalizeServiceContext(input.serviceContext);
    const serviceContextIssues = validateSaveWorkingSetServiceContext(rawServiceContext, input.set);
    if (serviceContextIssues.length > 0) {
      return failure({
        code: "invalidInput",
        message: "Service context is required before saving a working set.",
        issues: serviceContextIssues,
      });
    }

    const existingSet = input.existingSetId ? await this.planningSets.findById(input.existingSetId) : undefined;
    const antiphonContext = await this.validateAndNormalizeReferenceAntiphon(rawServiceContext, existingSet);
    if (!antiphonContext.success) return antiphonContext;
    const topicContext = await this.validateAndNormalizeReferenceTopic(antiphonContext.value, existingSet);
    if (!topicContext.success) return topicContext;
    const serviceContext = topicContext.value;
    const normalized = await this.validateAndNormalizeCatalogReferences(serviceContext, input.set, existingSet, input.allowLanguageDeviations === true);
    if (normalized.issues.length > 0) {
      return failure({ code: "invalidInput", message: "Catalog selections are invalid.", issues: normalized.issues });
    }

    const validation = validatePlanningPlan(normalized.set);
    if (!validation.valid) {
      return failure({ code: "invalidInput", message: "Working planning set is invalid.", issues: validation.issues });
    }

    if (input.existingSetId) {
      const existing = await this.planningSets.findById(input.existingSetId);
      if (!existing) {
        return failure({ code: "notFound", message: "Working planning set was not found." });
      }

      if (existing.status !== "working") {
        return failure({ code: "invalidStatus", message: "Final planning sets cannot be edited directly." });
      }
    }

    const duplicate = await this.findDuplicateService(serviceContext, input.existingSetId);
    if (duplicate) {
      return failure({ code: "invalidInput", message: `A service already exists for ${serviceContext.serviceDate} at ${serviceContext.serviceTime}.` });
    }

    const historyConflicts = await this.findHistoryConflictsForPlan({ ...(normalized.set as PlanningPlan & { status: "working" }), id: input.existingSetId ?? "candidate", serviceContext: normalized.serviceContext });
    if (historyConflicts.length > 0) return failure({ code: "invalidInput", message: "Working planning set conflicts with authoritative Completed history.", issues: historyConflicts.map((conflict) => ({ path: "historyNonRepeat", message: conflict.reason })) });

    return success(await this.planningSets.saveWorkingSet(normalized.set as PlanningPlan & { status: "working" }, normalized.serviceContext, input.existingSetId));
  }

  async finalizeWorkingSet(input: FinalizeWorkingSetInput): Promise<PlanningServiceResult<PersistedPlanningPlan>> {
    if (!canPerformPlanningAction(input.role, "saveFinalSet")) {
      return failure({ code: "permissionDenied", message: "Role cannot finalize a working planning set." });
    }

    const workingSet = await this.planningSets.findById(input.workingSetId);
    if (!workingSet) {
      return failure({ code: "notFound", message: "Working planning set was not found." });
    }

    if (workingSet.status !== "working") {
      return failure({ code: "invalidStatus", message: "Only working planning sets can be finalized." });
    }

    const finalPeopleIssues = await this.validateFinalPeople(workingSet.serviceContext);
    if (finalPeopleIssues.length > 0) {
      return failure({ code: "invalidInput", message: "Final service requires a concrete active priest and organist.", issues: finalPeopleIssues });
    }

    if (input.replaceFinalSetId) {
      const finalSet = await this.planningSets.findById(input.replaceFinalSetId);
      if (!finalSet) {
        return failure({ code: "notFound", message: "Final planning set to replace was not found." });
      }

      if (finalSet.status !== "final") {
        return failure({ code: "invalidStatus", message: "Only final planning sets can be replaced during finalization." });
      }
    }

    const finalSet: PlanningPlan & { status: "final" } = {
      status: "final",
      language: workingSet.language,
      rows: workingSet.rows,
    };
    const validation = validatePlanningPlan(finalSet);
    if (!validation.valid) {
      return failure({ code: "invalidInput", message: "Final planning set is invalid.", issues: validation.issues });
    }

    const melodyCollisions = await this.getAuthoritativeMelodyCollisions(finalSet.rows);
    if (melodyCollisions.length > 0) {
      return failure({
        code: "invalidInput",
        message: melodyCollisionSummary(melodyCollisions) ?? "Final planning set contains a melody collision.",
        issues: melodyCollisions.flatMap((collision) => collision.rows.map((row) => ({
          path: `rows.${row.rowId - 1}.song`,
          message: `This melody is also used in ${collision.rows.filter((candidate) => candidate.rowId !== row.rowId).map((candidate) => candidate.rowLabel).join(" and ")}.`,
        }))),
      });
    }

    const historyConflicts = await this.findHistoryConflictsForPlan({ ...workingSet, status: "final", rows: finalSet.rows });
    if (historyConflicts.length > 0) return failure({ code: "invalidInput", message: "Final planning set conflicts with authoritative Completed history.", issues: historyConflicts.map((conflict) => ({ path: "historyNonRepeat", message: conflict.reason })) });

    const persistedFinalSet = await this.planningSets.saveFinalSet(
      finalSet,
      workingSet.serviceContext,
      input.replaceFinalSetId ?? input.workingSetId,
    );

    if (persistedFinalSet.id !== input.workingSetId) {
      await this.planningSets.deleteById(input.workingSetId);
    }

    return success(persistedFinalSet);
  }

  async reopenFinalSet(input: ReopenFinalSetInput): Promise<PlanningServiceResult<PersistedPlanningPlan>> {
    if (input.role !== "admin") {
      return failure({ code: "permissionDenied", message: "Only admin can reopen a final planning set." });
    }
    const finalSet = await this.planningSets.findById(input.finalSetId);
    if (!finalSet) return failure({ code: "notFound", message: "Final planning set was not found." });
    if (finalSet.status !== "final") return failure({ code: "invalidStatus", message: "Only final planning sets can be reopened." });
    return success(await this.planningSets.saveWorkingSet(
      { status: "working", language: finalSet.language, rows: finalSet.rows },
      finalSet.serviceContext,
      finalSet.id,
    ));
  }

  async deletePlanningSet(input: DeletePlanningSetInput): Promise<PlanningServiceResult<{ deletedSetId: PlanningPlanId }>> {
    const set = await this.planningSets.findById(input.setId);
    if (!set) {
      return failure({ code: "notFound", message: "Planning set was not found." });
    }

    const action = set.status === "working" ? "deleteWorkingSet" : "deleteFinalSet";
    if (!canPerformPlanningAction(input.role, action)) {
      return failure({ code: "permissionDenied", message: "Role cannot delete this planning set." });
    }

    await this.completedServiceRecords.deleteBySourceFinalSetId(input.setId);
    await this.planningSets.deleteById(input.setId);
    return success({ deletedSetId: input.setId });
  }

  async reorderRows(input: ReorderRowsInput): Promise<PlanningServiceResult<PersistedPlanningPlan>> {
    if (!canPerformPlanningAction(input.role, "editWorkingSet")) {
      return failure({ code: "permissionDenied", message: "Role cannot reorder rows in a working planning set." });
    }

    const workingSet = await this.planningSets.findById(input.workingSetId);
    if (!workingSet) {
      return failure({ code: "notFound", message: "Working planning set was not found." });
    }

    if (workingSet.status !== "working") {
      return failure({ code: "invalidStatus", message: "Rows can only be reordered on a working planning set." });
    }

    const reorderedRows = reorderRowsByIndex(workingSet.rows, input.rowOrder);
    if (!reorderedRows) {
      return failure({ code: "invalidInput", message: "Row order must include every row index exactly once." });
    }

    const reorderedWorkingSet: PlanningPlan & { status: "working" } = {
      status: "working",
      language: workingSet.language,
      rows: reorderedRows,
    };

    return success(await this.planningSets.saveWorkingSet(reorderedWorkingSet, workingSet.serviceContext, input.workingSetId));
  }

  async updateCompletedRecord(input: UpdateCompletedRecordInput): Promise<PlanningServiceResult<CompletedServiceRecord>> {
    if (!canPerformPlanningAction(input.role, "editCompletedServiceRecord")) {
      return failure({ code: "permissionDenied", message: "Only admin can edit completed service records." });
    }
    const existing = await this.completedServiceRecords.findById(input.recordId);
    if (!existing) return failure({ code: "notFound", message: "Completed record was not found." });

    const rawServiceContext: ServiceContext = normalizeServiceContext(input.serviceContext);
    const serviceContextIssues = validateSaveWorkingSetServiceContext(rawServiceContext, input.set);
    if (serviceContextIssues.length > 0) return failure({ code: "invalidInput", message: "Service context is required before saving completed changes.", issues: serviceContextIssues });

    const antiphonContext = await this.validateAndNormalizeReferenceAntiphon(rawServiceContext, existing);
    if (!antiphonContext.success) return antiphonContext;
    const topicContext = await this.validateAndNormalizeReferenceTopic(antiphonContext.value, existing);
    if (!topicContext.success) return topicContext;
    const normalized = await this.validateAndNormalizeCatalogReferences(topicContext.value, input.set, existing, true, true);
    if (normalized.issues.length > 0) return failure({ code: "invalidInput", message: "Historical song references are invalid.", issues: normalized.issues });

    const historicalValidation = validateHistoricalCompletedSet(normalized.set);
    if (historicalValidation.length > 0) return failure({ code: "invalidInput", message: "Completed historical rows are malformed.", issues: historicalValidation });

    const duplicate = await this.findDuplicateService(normalized.serviceContext, undefined, input.recordId);
    if (duplicate) return failure({ code: "invalidInput", message: `A service already exists for ${normalized.serviceContext.serviceDate} at ${normalized.serviceContext.serviceTime}.` });

    const proposed: CompletedServiceRecord = {
      ...existing,
      serviceContext: normalized.serviceContext,
      set: { status: "final", language: normalized.serviceContext.language, rows: normalized.set.rows },
    };
    const [currentImpact, proposedImpact] = await Promise.all([
      this.findPlansImpactedByCompleted(existing),
      this.findPlansImpactedByCompleted(proposed),
    ]);
    const currentConflictKeys = new Set(currentImpact.map(historyConflictKey));
    const newlyImpacted = proposedImpact.filter((impact) => !currentConflictKeys.has(historyConflictKey(impact)));
    if (newlyImpacted.length > 0 && input.acceptPlanInvalidation !== true) {
      return failure({
        code: "invalidInput",
        message: "Completed correction would invalidate active plans. Confirmation is required.",
        issues: newlyImpacted.map((impact) => ({
          path: `retroactivePlan.${impact.planId}`,
          message: `${impact.reason} ${impact.planStatus === "final" ? "This Final plan will move to Working." : "This Working plan will require revision."}`,
        })),
      });
    }

    try {
      return success(await this.completedServiceRecords.update(input.recordId, normalized.serviceContext, proposed.set, [...new Set(newlyImpacted.map((impact) => impact.planId))]));
    } catch {
      return failure({ code: "notFound", message: "Completed record was not found." });
    }
  }

  async deleteCompletedRecord(input: DeleteCompletedRecordInput): Promise<PlanningServiceResult<{ deletedRecordId: string }>> {
    if (!canPerformPlanningAction(input.role, "deleteCompletedServiceRecord")) {
      return failure({ code: "permissionDenied", message: "Only admin can delete completed service records." });
    }

    const existing = await this.completedServiceRecords.findById(input.recordId);
    if (!existing) {
      return failure({ code: "notFound", message: "Completed record was not found." });
    }

    await this.completedServiceRecords.deleteById(input.recordId);
    return success({ deletedRecordId: input.recordId });
  }

  async completeFinalSet(input: CompleteFinalSetInput): Promise<PlanningServiceResult<CompletedServiceRecord>> {
    if (!canPerformPlanningAction(input.role, "convertFinalSetToCompletedServiceRecord")) {
      return failure({ code: "permissionDenied", message: "Role cannot complete a final planning set." });
    }

    const finalSet = await this.planningSets.findById(input.finalSetId);
    if (!finalSet) {
      return failure({ code: "notFound", message: "Final planning set was not found." });
    }

    if (finalSet.status !== "final") {
      return failure({ code: "invalidStatus", message: "Only final planning sets can be completed." });
    }

    if (isFuturePragueDate(finalSet.serviceContext.serviceDate, this.now())) {
      return failure({ code: "invalidInput", message: `Future service ${finalSet.serviceContext.serviceDate} at ${finalSet.serviceContext.serviceTime || "Time missing"} cannot be completed.` });
    }

    const outcome = await this.persistFinalSetCompletion(finalSet as PersistedPlanningPlan & { status: "final" }, this.now());
    if (outcome.status === "notFound") {
      return failure({ code: "notFound", message: "Final planning set was not found." });
    }
    if (outcome.status === "notFinal") {
      return failure({ code: "invalidStatus", message: "Only final planning sets can be completed." });
    }
    return success(outcome.record);
  }

  private async reconcilePastFinalSets(): Promise<void> {
    const now = this.now();
    const overdue = (await this.planningSets.list())
      .filter((set): set is PersistedPlanningPlan & { status: "final" } => set.status === "final" && isPastPragueDate(set.serviceContext.serviceDate, now))
      .sort((left, right) => left.serviceContext.serviceDate.localeCompare(right.serviceContext.serviceDate) || left.id.localeCompare(right.id));

    for (const finalSet of overdue) {
      // A concurrent reconciliation/manual completion may win after the list snapshot.
      // notFound/notFinal are therefore benign here; a completed outcome is already persisted.
      await this.persistFinalSetCompletion(finalSet, now);
    }
  }

  private async persistFinalSetCompletion(
    finalSet: PersistedPlanningPlan & { status: "final" },
    completedAt: Date,
  ): Promise<FinalSetCompletionPersistenceResult> {
    if (this.finalSetCompletion) {
      return this.finalSetCompletion.completeFinalSet(finalSet.id, completedAt);
    }

    // Memory/custom runtimes use one serialized fallback completion boundary.
    // PostgreSQL supplies the runtime-specific atomic repository below.
    return this.withFallbackCompletionLock(async () => {
      const current = await this.planningSets.findById(finalSet.id);
      if (!current) return { status: "notFound" };
      if (current.status !== "final") return { status: "notFinal" };
      const record = await this.completedServiceRecords.createFromFinalSet({
        sourceFinalSetId: current.id,
        set: { status: "final", language: current.language, rows: current.rows },
        serviceContext: current.serviceContext,
        completedAt,
      });
      await this.planningSets.deleteById(current.id);
      return { status: "completed", record };
    });
  }

  private async withFallbackCompletionLock<T>(operation: () => Promise<T>): Promise<T> {
    const previous = this.fallbackCompletionTail;
    let release!: () => void;
    this.fallbackCompletionTail = new Promise<void>((resolve) => { release = resolve; });
    await previous;
    try {
      return await operation();
    } finally {
      release();
    }
  }

  private async getAuthoritativeMelodyCollisions(rows: PlanningRow[]): Promise<MelodyCollision[]> {
    if (!this.referenceMelodyClasses) return [];
    const songIds = rows.flatMap((row) => row.song?.songId ? [row.song.songId] : []);
    const memberships = await this.referenceMelodyClasses.getClassMemberships(songIds);
    const classBySongId = new Map(memberships.map((membership) => [membership.songId, membership.melodyClassId]));
    return findMelodyCollisions(rows.map((row, index) => ({
      rowId: index + 1,
      rowLabel: `Row ${index + 1}`,
      songId: row.song?.songId,
      melodyClassId: row.song?.songId ? classBySongId.get(row.song.songId) : undefined,
    })));
  }

  private async validateAndNormalizeReferenceAntiphon(
    serviceContext: ServiceContext,
    existing?: PersistedPlanningPlan | CompletedServiceRecord,
  ): Promise<PlanningServiceResult<ServiceContext>> {
    const candidate = (serviceContext as ServiceContext & { referenceAntiphon?: unknown }).referenceAntiphon;
    if (candidate === undefined) {
      return success({ ...serviceContext, referenceAntiphon: undefined });
    }

    if (!isServiceAntiphonReference(candidate)) {
      return failure({
        code: "invalidInput",
        message: "Authoritative antiphon selection is malformed.",
        issues: [{ path: "serviceContext.referenceAntiphon", message: "Select an antiphon from the authoritative catalog." }],
      });
    }

    if (!serviceAntiphonMatchesLanguage(candidate, serviceContext.language)) {
      return failure({
        code: "invalidInput",
        message: "Selected antiphon must match the service language.",
        issues: [{ path: "serviceContext.referenceAntiphon", message: "Selected antiphon must match the service language." }],
      });
    }

    const previous = existing?.serviceContext.referenceAntiphon;
    if (previous && sameServiceAntiphonReference(previous, candidate)) {
      return success({ ...serviceContext, referenceAntiphon: { ...previous } });
    }

    if (!isAcceptedReferenceAntiphonId(candidate.id)) {
      return failure({
        code: "invalidInput",
        message: "Authoritative antiphon identity is invalid.",
        issues: [{ path: "serviceContext.referenceAntiphon.id", message: "Antiphon id must be a positive Czech or Polish authoritative id." }],
      });
    }

    if (!this.referenceAntiphons) {
      return failure({ code: "invalidInput", message: "Authoritative antiphon selection is unavailable in this runtime." });
    }

    const authoritative = await this.referenceAntiphons.getById(candidate.id);
    const expectedLanguage = serviceAntiphonLanguageFromId(candidate.id);
    if (!authoritative || !expectedLanguage || authoritative.language !== expectedLanguage) {
      return failure({ code: "notFound", message: "Authoritative antiphon was not found." });
    }

    return success({ ...serviceContext, referenceAntiphon: serviceAntiphonSnapshot(authoritative) });
  }

  private async validateAndNormalizeReferenceTopic(
    serviceContext: ServiceContext,
    existing?: PersistedPlanningPlan | CompletedServiceRecord,
  ): Promise<PlanningServiceResult<ServiceContext>> {
    const candidate = (serviceContext as ServiceContext & { referenceTopic?: unknown }).referenceTopic;
    if (candidate === undefined) return success({ ...serviceContext, referenceTopic: undefined });
    if (!isServiceTopicReference(candidate)) {
      return failure({ code: "invalidInput", message: "Authoritative Topic selection is malformed.", issues: [{ path: "serviceContext.referenceTopic", message: "Select a Topic from the authoritative catalog." }] });
    }
    if (!serviceTopicMatchesLanguage(candidate, serviceContext.language)) {
      return failure({ code: "invalidInput", message: "Selected topic must match the service language.", issues: [{ path: "serviceContext.referenceTopic", message: "Selected topic must match the service language." }] });
    }
    const previous = existing?.serviceContext.referenceTopic;
    if (previous && sameServiceTopicReference(previous, candidate)) return success({ ...serviceContext, referenceTopic: { ...previous } });
    if (!isAcceptedReferenceTopicId(candidate.id)) {
      return failure({ code: "invalidInput", message: "Authoritative Topic identity is invalid.", issues: [{ path: "serviceContext.referenceTopic.id", message: "Topic id must be a Czech or Polish authoritative thematic-section id." }] });
    }
    if (!this.referenceTopics) return failure({ code: "invalidInput", message: "Authoritative Topic selection is unavailable in this runtime." });
    const authoritative = await this.referenceTopics.getSectionById(candidate.id);
    const expectedLanguage = serviceTopicLanguageFromId(candidate.id);
    if (!authoritative || !expectedLanguage || authoritative.language !== expectedLanguage) return failure({ code: "notFound", message: "Authoritative Topic was not found." });
    return success({ ...serviceContext, referenceTopic: serviceTopicSnapshot(authoritative) });
  }

  private async validateAndNormalizeCatalogReferences<TSet extends PlanningPlan>(serviceContext: ServiceContext, set: TSet, existing?: PersistedPlanningPlan | CompletedServiceRecord, allowLanguageDeviations = false, allowHistoricalTruthRows = false): Promise<{ serviceContext: ServiceContext; set: TSet; issues: { path: string; message: string }[] }> {
    const issues: { path: string; message: string }[] = [];
    if (!this.enforceCatalogSelections) {
      return {
        serviceContext: { ...serviceContext, priest: { ...serviceContext.priest }, organist: { ...serviceContext.organist } },
        set: { ...set, rows: set.rows.map((row) => ({ ...(row.song ? { song: { ...row.song } } : {}), ...(row.note ? { note: row.note } : {}) })) } as TSet,
        issues,
      };
    }
    const normalizedContext: ServiceContext = {
      ...serviceContext,
      priest: { ...serviceContext.priest },
      organist: { ...serviceContext.organist },
    };
    const normalizedRows: PlanningRow[] = set.rows.map((row) => ({
      ...(row.song ? { song: { ...row.song } } : {}),
      ...(row.note ? { note: row.note } : {}),
    }));
    const unchangedSongs = createSongSnapshotMultiset(existing ? getRowsFromExisting(existing) : []);

    for (const [role, ref] of [["priest", normalizedContext.priest], ["organist", normalizedContext.organist]] as const) {
      const previous = existing?.serviceContext[role];
      if (!ref.id) {
        if (ref.displayName === "Anonymous") continue;
        issues.push({ path: role, message: `${role} must be selected from the person catalog or explicitly set to Anonymous.` });
        continue;
      }
      if (previous?.id === ref.id && previous.displayName === ref.displayName) continue;
      const person = await this.catalog.findPersonById(ref.id);
      if (!isEligiblePerson(person, role)) issues.push({ path: role, message: `${role} is not active for the selected role.` });
      else ref.displayName = person!.displayName;
    }

    for (const [index, row] of normalizedRows.entries()) {
      if (!row.song) continue;
      if (allowHistoricalTruthRows && row.song.number.trim() === "0") {
        if (row.song.language !== "czech" && row.song.language !== "polish") issues.push({ path: `rows.${index}.song.language`, message: "Historical zero must retain Czech or Polish language." });
        else row.song = { language: row.song.language, number: "0" };
        continue;
      }
      if (!row.song.songId) { issues.push({ path: `rows.${index}.song`, message: "Positive historical song number must be selected from the catalog." }); continue; }
      if (consumeUnchangedSongSnapshot(unchangedSongs, row.song)) {
        if (!allowLanguageDeviations && !languagesForService(normalizedContext.language).includes(row.song.language)) {
          issues.push({ path: `rows.${index}.song`, message: "Song is not active for this service language." });
        }
        continue;
      }
      const referenceSong = await this.referenceSongs?.getById(row.song.songId);
      if (referenceSong) {
        if (!allowLanguageDeviations && !languagesForService(normalizedContext.language).includes(referenceSong.language)) { issues.push({ path: `rows.${index}.song`, message: "Song is not active for this service language." }); continue; }
        row.song = { songId: referenceSong.id, language: referenceSong.language, number: referenceSong.displayNumber, title: referenceSong.title };
        continue;
      }
      const song = await this.catalog.findSongById(row.song.songId);
      if (!song) { issues.push({ path: `rows.${index}.song`, message: "Song was not found in the catalog." }); continue; }
      if (!song.active) { issues.push({ path: `rows.${index}.song`, message: "Song is not active." }); continue; }
      if (!allowLanguageDeviations && !languagesForService(normalizedContext.language).includes(song.language)) { issues.push({ path: `rows.${index}.song`, message: "Song is not active for this service language." }); continue; }
      row.song = { songId: song.songId, language: song.language, number: song.number, title: song.title };
    }

    return { serviceContext: normalizedContext, set: { ...set, rows: normalizedRows } as TSet, issues };
  }

  private async annotateRevisionStates(sets: PersistedPlanningPlan[]): Promise<PersistedPlanningPlan[]> {
    if (!this.referenceMelodyClasses || sets.length === 0) return sets;
    return Promise.all(sets.map(async (set) => {
      const conflicts = await this.findHistoryConflictsForPlan(set);
      if (conflicts.length === 0) return { ...set, needsRevision: undefined };
      return {
        ...set,
        needsRevision: {
          reason: `Needs revision: ${conflicts.map((conflict) => conflict.reason).join(" ")}`,
          conflictingCompletedRecordIds: [...new Set(conflicts.map((conflict) => conflict.completedRecordId))],
          conflictingRowIndexes: [...new Set(conflicts.map((conflict) => conflict.planRowIndex))].sort((left, right) => left - right),
        },
      };
    }));
  }

  private async findPlansImpactedByCompleted(record: CompletedServiceRecord): Promise<HistoryConflict[]> {
    const plans = await this.planningSets.list();
    const impacts: HistoryConflict[] = [];
    for (const plan of plans) impacts.push(...await this.findHistoryConflictsForPlan(plan, [record]));
    return impacts;
  }

  private async findHistoryConflictsForPlan(plan: PersistedPlanningPlan, completedOverride?: CompletedServiceRecord[]): Promise<HistoryConflict[]> {
    if (!this.referenceMelodyClasses) return [];
    const completed = completedOverride ?? await this.completedServiceRecords.list();
    if (completed.length === 0) return [];
    const months = Math.max(0, Math.floor(await this.melodyNonRepetitionMonths()));
    const planSongIds = plan.rows.flatMap((row) => row.song?.songId ? [row.song.songId] : []);
    const completedSongIds = completed.flatMap((record) => record.set.rows.flatMap((row) => row.song?.songId ? [row.song.songId] : []));
    const allIds = [...new Set([...planSongIds, ...completedSongIds])];
    const memberships = await this.referenceMelodyClasses.getClassMemberships(allIds);
    const classBySong = new Map(memberships.map((membership) => [membership.songId, membership.melodyClassId]));
    const classOf = (songId: string) => classBySong.get(songId) ?? `reference-singleton:${songId}`;
    const conflicts: HistoryConflict[] = [];
    for (const record of completed) {
      if (!isWithinCalendarMonths(plan.serviceContext.serviceDate, record.serviceContext.serviceDate, months)) continue;
      for (const [planRowIndex, planRow] of plan.rows.entries()) {
        if (!planRow.song?.songId) continue;
        for (const [completedRowIndex, historicalRow] of record.set.rows.entries()) {
          if (!historicalRow.song?.songId || classOf(planRow.song.songId) !== classOf(historicalRow.song.songId)) continue;
          conflicts.push({
            planId: plan.id,
            planStatus: plan.status,
            completedRecordId: record.id,
            planRowIndex,
            completedRowIndex,
            reason: `${plan.serviceContext.serviceDate} ${plan.serviceContext.serviceTime}: song ${planRow.song.number} conflicts with Completed ${record.serviceContext.serviceDate} ${record.serviceContext.serviceTime}, song ${historicalRow.song.number}, within the ${months}-month melody non-repetition period.`,
          });
        }
      }
    }
    return conflicts;
  }

  private async validateFinalPeople(serviceContext: ServiceContext): Promise<{ path: string; message: string }[]> {
    const issues: { path: string; message: string }[] = [];
    for (const [role, ref] of [["priest", serviceContext.priest], ["organist", serviceContext.organist]] as const) {
      if (!ref.id) { issues.push({ path: role, message: `${role} must be a concrete active person before finalization.` }); continue; }
      if (!this.enforceCatalogSelections) continue;
      const person = await this.catalog.findPersonById(ref.id);
      if (!isEligiblePerson(person, role)) issues.push({ path: role, message: `${role} is not active for the selected role.` });
    }
    return issues;
  }

  private async findDuplicateService(serviceContext: ServiceContext, currentSetId?: PlanningPlanId, currentCompletedRecordId?: string): Promise<PersistedPlanningPlan | CompletedServiceRecord | undefined> {
    const sets = await this.planningSets.list();
    const activeDuplicate = sets.find((set) => set.id !== currentSetId && set.serviceContext.serviceDate === serviceContext.serviceDate && normalizeServiceTime(set.serviceContext.serviceTime) === serviceContext.serviceTime);
    if (activeDuplicate) return activeDuplicate;
    const completed = await this.completedServiceRecords.list();
    return completed.find((record) => record.id !== currentCompletedRecordId && record.serviceContext.serviceDate === serviceContext.serviceDate && normalizeServiceTime(record.serviceContext.serviceTime) === serviceContext.serviceTime);
  }
}

type HistoryConflict = { planId: PlanningPlanId; planStatus: "working" | "final"; completedRecordId: string; planRowIndex: number; completedRowIndex: number; reason: string };

function historyConflictKey(conflict: HistoryConflict): string {
  return `${conflict.planId}�${conflict.completedRecordId}�${conflict.planRowIndex}�${conflict.completedRowIndex}`;
}

function validateHistoricalCompletedSet(set: PlanningPlan): { path: string; message: string }[] {
  const issues: { path: string; message: string }[] = [];
  if (set.status !== "final") issues.push({ path: "status", message: "Completed snapshot status must be final." });
  if (set.language !== "czech" && set.language !== "polish" && set.language !== "mixed") issues.push({ path: "language", message: "Completed snapshot language is invalid." });
  if (!Array.isArray(set.rows)) return [...issues, { path: "rows", message: "Completed rows must be an array." }];
  set.rows.forEach((row, index) => {
    if (!row || typeof row !== "object") { issues.push({ path: `rows.${index}`, message: "Historical row is malformed." }); return; }
    if (!row.song) return;
    if ((row.song.language !== "czech" && row.song.language !== "polish") || typeof row.song.number !== "string" || !row.song.number.trim()) issues.push({ path: `rows.${index}.song`, message: "Historical song reference is malformed." });
    if (row.song.songId !== undefined && (typeof row.song.songId !== "string" || !row.song.songId.trim())) issues.push({ path: `rows.${index}.song.songId`, message: "Historical catalog song ID is malformed." });
  });
  return issues;
}

function isWithinCalendarMonths(leftDate: string, rightDate: string, months: number): boolean {
  const left = Date.parse(`${leftDate}T00:00:00Z`);
  const right = Date.parse(`${rightDate}T00:00:00Z`);
  if (!Number.isFinite(left) || !Number.isFinite(right)) return false;
  return right >= addMonthsUtc(left, -months) && right <= addMonthsUtc(left, months);
}
function addMonthsUtc(value: number, months: number): number {
  const date = new Date(value);
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + months, date.getUTCDate());
}

function normalizeServiceContext(context: ServiceContext): ServiceContext {
  return {
    ...context,
    serviceTime: normalizeServiceTime(context.serviceTime),
    ...(context.note?.trim() ? { note: context.note.trim() } : { note: undefined }),
    ...(isServiceAntiphonReference(context.referenceAntiphon)
      ? { referenceAntiphon: { ...context.referenceAntiphon } }
      : context.referenceAntiphon === undefined
        ? { referenceAntiphon: undefined }
        : { referenceAntiphon: context.referenceAntiphon as never }),
    ...(isServiceTopicReference(context.referenceTopic)
      ? { referenceTopic: { ...context.referenceTopic } }
      : context.referenceTopic === undefined
        ? { referenceTopic: undefined }
        : { referenceTopic: context.referenceTopic as never }),
    ...(context.antiphonKey?.trim() ? { antiphonKey: context.antiphonKey.trim() } : { antiphonKey: undefined }),
    ...(context.liturgicalSeasonKey?.trim() ? { liturgicalSeasonKey: context.liturgicalSeasonKey.trim() } : { liturgicalSeasonKey: undefined }),
  };
}

function isServiceAntiphonReference(value: unknown): value is ServiceAntiphonReference {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  const keys = Object.keys(record).sort();
  if (keys.some((key) => !["displayNumber", "id", "sourceUrl", "title"].includes(key))) return false;
  if (!keys.includes("id") || !keys.includes("displayNumber") || !keys.includes("title")) return false;
  if (typeof record.id !== "string" || typeof record.displayNumber !== "string" || typeof record.title !== "string") return false;
  if (record.sourceUrl !== undefined && (typeof record.sourceUrl !== "string" || !record.sourceUrl.trim())) return false;
  return record.id.trim() === record.id && record.displayNumber.trim().length > 0 && record.title.trim().length > 0;
}

function isAcceptedReferenceAntiphonId(id: string): boolean {
  return /^(czech|polish):[1-9]\d*$/.test(id);
}

function isServiceTopicReference(value: unknown): value is ServiceTopicReference {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  const keys = Object.keys(record).sort();
  if (keys.length !== 2 || keys[0] !== "id" || keys[1] !== "title") return false;
  return typeof record.id === "string" && record.id.trim() === record.id && record.id.length > 0 && typeof record.title === "string" && record.title.trim().length > 0;
}

function isAcceptedReferenceTopicId(id: string): boolean {
  return /^(czech|polish):[a-z0-9][a-z0-9:-]*$/.test(id);
}

function sameServiceTopicReference(left: ServiceTopicReference, right: ServiceTopicReference): boolean {
  return left.id === right.id && left.title === right.title;
}

function serviceTopicSnapshot(section: ReferenceThematicSection): ServiceTopicReference {
  return { id: section.id, title: section.title };
}

function sameServiceAntiphonReference(left: ServiceAntiphonReference, right: ServiceAntiphonReference): boolean {
  return left.id === right.id && left.displayNumber === right.displayNumber &&
    left.title === right.title && (left.sourceUrl ?? "") === (right.sourceUrl ?? "");
}

function serviceAntiphonSnapshot(record: ReferenceAntiphonRecord): ServiceAntiphonReference {
  return { id: record.id, displayNumber: record.displayNumber, title: record.title, ...(record.sourceUrl ? { sourceUrl: record.sourceUrl } : {}) };
}

function getRowsFromExisting(existing: PersistedPlanningPlan | CompletedServiceRecord): PlanningRow[] {
  return "set" in existing ? existing.set.rows : existing.rows;
}

function createSongSnapshotMultiset(rows: PlanningRow[]): Map<string, number> {
  const multiset = new Map<string, number>();
  for (const row of rows) {
    if (!row.song?.songId) continue;
    const key = songSnapshotKey(row.song);
    multiset.set(key, (multiset.get(key) ?? 0) + 1);
  }
  return multiset;
}

function consumeUnchangedSongSnapshot(multiset: Map<string, number>, song: NonNullable<PlanningRow["song"]>): boolean {
  const key = songSnapshotKey(song);
  const count = multiset.get(key) ?? 0;
  if (count <= 0) return false;
  if (count === 1) multiset.delete(key);
  else multiset.set(key, count - 1);
  return true;
}

function songSnapshotKey(song: NonNullable<PlanningRow["song"]>): string {
  return JSON.stringify({ songId: song.songId, language: song.language, number: song.number, title: song.title });
}

export function pragueCalendarDate(now: Date): string {
  return new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Prague", year: "numeric", month: "2-digit", day: "2-digit" }).format(now);
}

export function isPastPragueDate(serviceDate: string, now: Date): boolean {
  return serviceDate < pragueCalendarDate(now);
}

function isFuturePragueDate(serviceDate: string, now: Date): boolean {
  return serviceDate > pragueCalendarDate(now);
}

function reorderRowsByIndex(rows: PlanningRow[], rowOrder: number[]): PlanningRow[] | undefined {
  if (rows.length !== rowOrder.length) {
    return undefined;
  }

  const seen = new Set<number>();
  const reorderedRows: PlanningRow[] = [];

  for (const index of rowOrder) {
    if (!Number.isInteger(index) || index < 0 || index >= rows.length || seen.has(index)) {
      return undefined;
    }

    seen.add(index);
    reorderedRows.push(rows[index]);
  }

  return reorderedRows;
}

function validateSaveWorkingSetServiceContext(
  serviceContext: SaveWorkingSetServiceContext,
  set: PlanningPlan,
): { path: string; message: string }[] {
  return [
    ...(serviceContext.language !== set.language
      ? [{ path: "serviceContext.language", message: "Service context language must match the planning set language." }]
      : []),
    ...(!serviceContext.serviceDate.trim() ? [{ path: "serviceDate", message: "Service date is required." }] : []),
    ...(!isValidServiceTime(serviceContext.serviceTime) ? [{ path: "serviceTime", message: "Service time is required in HH:mm format between 00:00 and 23:59." }] : []),
    ...(!serviceContext.priest.displayName.trim() ? [{ path: "priest", message: "Priest is required." }] : []),
    ...(!serviceContext.organist.displayName.trim() ? [{ path: "organist", message: "Organist is required." }] : []),
  ];
}

import type { Pool, PoolClient } from "pg";
import type { ActorIdentity } from "./interaction-contracts";
import { appendAuditEvent, humanAuditActor } from "./audit-history";
import {
  findNonRepetitionPlanConflicts,
  melodyWindowConflictMessage,
  validateMelodyWindowMonths,
  type MelodyWindowResult,
  type NonRepetitionPlanMelodyUsage,
} from "./non-repetition-period";

type PersistedUsageRow = {
  plan_id: unknown;
  status: unknown;
  service_date: unknown;
  melody_class_id: unknown;
};

export class PostgresNonRepetitionPeriodService {
  constructor(private readonly pool: Pool) {}

  async get(actor: ActorIdentity): Promise<MelodyWindowResult> {
    if (!actor.userId || !actor.role) {
      return failure("permissionDenied", "An active actor is required to read melody non-repetition configuration.");
    }
    const { rows } = await this.pool.query("select months from melody_non_repetition_config where id = 'global'");
    return success(Number(rows[0]?.months ?? 2));
  }

  async set(actor: ActorIdentity, months: unknown): Promise<MelodyWindowResult> {
    if (actor.role !== "admin") {
      return failure("permissionDenied", "Only admin can change the melody non-repetition period.");
    }
    if (!validateMelodyWindowMonths(months)) {
      return failure("invalidInput", "Melody Protection must be between 0 and 12 calendar months.");
    }

    const client = await this.pool.connect();
    try {
      await client.query("begin");
      await client.query("lock table service_contexts, service_sets, service_set_rows, reference_song_melody_memberships in share mode");
      const currentResult = await client.query("select months from melody_non_repetition_config where id = 'global' for update");
      const beforeMonths = Number(currentResult.rows[0]?.months ?? 2);
      const usages = await listSavedPlanMelodyUsages(client);
      const conflicts = findNonRepetitionPlanConflicts(usages, months);
      if (conflicts.length > 0) {
        await client.query("rollback");
        return {
          success: false,
          error: {
            code: "conflict",
            message: melodyWindowConflictMessage(conflicts, months),
            conflicts,
          },
        };
      }

      if (beforeMonths !== months) {
        await client.query(
          "insert into melody_non_repetition_config (id, months) values ('global', $1) on conflict (id) do update set months = excluded.months, updated_at = now()",
          [months],
        );
        await appendAuditEvent(client, {
          actor: humanAuditActor(actor),
          action: "knowledge.nonRepetition.set",
          objectKind: "nonRepetitionConfig",
          objectRef: "global",
          beforeState: { months: beforeMonths },
          afterState: { months },
        });
      }
      await client.query("commit");
      return success(months);
    } catch (error) {
      await rollbackQuietly(client);
      throw error;
    } finally {
      client.release();
    }
  }
}

async function listSavedPlanMelodyUsages(client: PoolClient): Promise<NonRepetitionPlanMelodyUsage[]> {
  const result = await client.query(
    `select distinct
       ss.id as plan_id,
       ss.status,
       sc.service_date,
       m.class_id as melody_class_id
     from service_sets ss
     join service_contexts sc on sc.id = ss.service_context_id
     join service_set_rows sr on sr.service_set_id = ss.id
     join reference_song_melody_memberships m on m.reference_song_id = sr.song_id
     where ss.status in ('working', 'final')
     order by sc.service_date, ss.id, m.class_id`,
  );

  return (result.rows as PersistedUsageRow[]).map((row) => ({
    planId: String(row.plan_id),
    status: persistedPlanStatus(row.status),
    serviceDate: normalizeDate(row.service_date),
    melodyClassId: String(row.melody_class_id),
  }));
}

function persistedPlanStatus(value: unknown): NonRepetitionPlanMelodyUsage["status"] {
  if (value === "working" || value === "final") return value;
  throw new Error(`Unexpected saved planning-set status '${String(value)}'.`);
}

function normalizeDate(value: unknown): string {
  if (value instanceof Date) return value.toISOString().slice(0, 10);
  return String(value).slice(0, 10);
}

async function rollbackQuietly(client: PoolClient): Promise<void> {
  try {
    await client.query("rollback");
  } catch {
    // Preserve the original failure.
  }
}

function success(months: number): MelodyWindowResult {
  return { success: true, value: { months } };
}

function failure(code: "permissionDenied" | "invalidInput", message: string): MelodyWindowResult {
  return { success: false, error: { code, message } };
}

import type { Pool } from "pg";
import type {
  ReferenceAntiphonPage,
  ReferenceAntiphonProvider,
  ReferenceAntiphonQuery,
  ReferenceAntiphonRecord,
} from "./reference-antiphon-contract";

type Row = {
  id: string;
  language: "czech" | "polish";
  canonical_number: number;
  title: string;
  source_url: string | null;
};

function mapRecord(row: Row): ReferenceAntiphonRecord {
  return {
    id: row.id,
    language: row.language,
    canonicalNumber: row.canonical_number,
    displayNumber: String(row.canonical_number),
    title: row.title,
    ...(row.source_url ? { sourceUrl: row.source_url } : {}),
  };
}

const ORDER = "case language when 'polish' then 0 else 1 end, canonical_number asc, id asc";

/** Read-only provider whose filtering, ordering, counts, and paging execute in PostgreSQL. */
export class PostgresReferenceAntiphonProvider implements ReferenceAntiphonProvider {
  constructor(private readonly pool: Pool) {}

  async list(input: ReferenceAntiphonQuery = {}): Promise<ReferenceAntiphonPage> {
    const values: unknown[] = [];
    const conditions: string[] = [];
    if ((input.language ?? "all") !== "all") {
      values.push(input.language);
      conditions.push(`language = $${values.length}`);
    }
    const search = input.search?.trim() ?? "";
    if (search) {
      if (/^\d+$/.test(search)) {
        values.push(`${search}%`);
        conditions.push(`canonical_number::text like $${values.length}`);
      } else {
        values.push(`%${search}%`);
        conditions.push(`title ilike $${values.length}`);
      }
    }
    const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
    const total = Number((await this.pool.query(`SELECT count(*)::int AS count FROM reference_antiphons ${where}`, values)).rows[0].count);
    const pageSize = input.pageSize ?? 50;
    const pageCount = Math.max(1, Math.ceil(total / pageSize));
    const page = Math.min(input.page ?? 0, pageCount - 1);
    const pageValues = [...values, pageSize, page * pageSize];
    const rows = (await this.pool.query(
      `SELECT id, language, canonical_number, title, source_url FROM reference_antiphons ${where} ORDER BY ${ORDER} LIMIT $${pageValues.length - 1} OFFSET $${pageValues.length}`,
      pageValues,
    )).rows as Row[];
    return { records: rows.map(mapRecord), total, page, pageSize, pageCount, counts: await this.counts() };
  }

  async getById(id: string): Promise<ReferenceAntiphonRecord | undefined> {
    const row = (await this.pool.query(
      "SELECT id, language, canonical_number, title, source_url FROM reference_antiphons WHERE id = $1",
      [id],
    )).rows[0] as Row | undefined;
    return row ? mapRecord(row) : undefined;
  }

  private async counts(): Promise<ReferenceAntiphonPage["counts"]> {
    const row = (await this.pool.query(`SELECT
      count(*)::int AS all,
      count(*) FILTER (WHERE language = 'czech')::int AS czech,
      count(*) FILTER (WHERE language = 'polish')::int AS polish
      FROM reference_antiphons`)).rows[0];
    return { all: Number(row.all), czech: Number(row.czech), polish: Number(row.polish) };
  }
}

import type { Pool } from "pg";
import { displayReferenceNumber, normalizeReferenceNumberQuery, type ReferenceCatalogPage, type ReferenceCatalogQuery, type ReferenceCatalogRecord } from "./reference-catalog-contract";

type DatabaseRow = { id: string; language: "czech" | "polish"; canonical_number: number; title: string; source_url: string | null };
const ORDER_BY_NATURAL_NUMBER = `
  CASE WHEN canonical_number < 1000 THEN canonical_number WHEN canonical_number % 10 <> 0 THEN canonical_number / 10 WHEN canonical_number % 100 <> 0 THEN canonical_number / 100 WHEN canonical_number % 1000 <> 0 THEN canonical_number / 1000 ELSE canonical_number END,
  CASE WHEN canonical_number < 1000 THEN 0 WHEN canonical_number % 10 <> 0 THEN canonical_number % 10 WHEN canonical_number % 100 <> 0 THEN (canonical_number / 10) % 10 WHEN canonical_number % 1000 <> 0 THEN (canonical_number / 100) % 10 ELSE 0 END,
  language, title, id`;

function numberPredicate(search: string, values: unknown[]): string {
  if (/^[1-9]\d{3,}$/.test(search)) { values.push(Number(search)); return `canonical_number = $${values.length}`; }
  const family = search.match(/^([1-9]\d*)\/?$/);
  if (family) {
    values.push(Number(family[1]));
    const base = `CASE WHEN canonical_number < 1000 THEN canonical_number WHEN canonical_number % 10 <> 0 THEN canonical_number / 10 WHEN canonical_number % 100 <> 0 THEN canonical_number / 100 WHEN canonical_number % 1000 <> 0 THEN canonical_number / 1000 ELSE canonical_number END`;
    const variant = `CASE WHEN canonical_number < 1000 THEN 0 WHEN canonical_number % 10 <> 0 THEN canonical_number % 10 WHEN canonical_number % 100 <> 0 THEN (canonical_number / 10) % 10 WHEN canonical_number % 1000 <> 0 THEN (canonical_number / 100) % 10 ELSE 0 END`;
    return `${base} = $${values.length}${search.endsWith("/") ? ` AND ${variant} > 0` : ""}`;
  }
  const canonical = normalizeReferenceNumberQuery(search);
  values.push(canonical ?? -1); return `canonical_number = $${values.length}`;
}

function mapRecord(row: DatabaseRow): ReferenceCatalogRecord {
  const expectedId = `${row.language}:${row.canonical_number}`;
  if (row.id !== expectedId) throw new Error("Persisted reference catalog stable ID is invalid.");
  return { id: row.id, language: row.language, canonicalNumber: row.canonical_number, displayNumber: displayReferenceNumber(row.canonical_number), title: row.title, ...(row.source_url ? { sourceUrl: row.source_url } : {}) };
}

/** Read-only provider whose filtering, ordering, counts and pagination execute in PostgreSQL. */
export class PostgresReferenceCatalogProvider {
  constructor(private readonly pool: Pool) {}

  async list(input: ReferenceCatalogQuery = {}): Promise<ReferenceCatalogPage> {
    const language = input.language ?? "all"; const search = input.search?.trim() ?? "";
    const pageSize = input.pageSize ?? 50;
    if (!Number.isInteger(pageSize) || pageSize <= 0) throw new Error("Reference catalog pageSize must be a positive integer.");
    const conditions: string[] = []; const values: unknown[] = [];
    if (language !== "all") { values.push(language); conditions.push(`language = $${values.length}`); }
    if (search) {
      if (/^[1-9]\d*(?:\/[1-8]?)?$/.test(search)) conditions.push(numberPredicate(search, values));
      else { values.push(`%${search}%`); conditions.push(`title ILIKE $${values.length}`); }
    }
    const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
    const total = Number((await this.pool.query(`SELECT count(*)::integer AS count FROM reference_catalog_songs ${where}`, values)).rows[0]?.count ?? 0);
    const pageCount = Math.max(1, Math.ceil(total / pageSize)); const page = Math.min(Math.max(input.page ?? 0, 0), pageCount - 1);
    const pageValues = [...values, pageSize, page * pageSize];
    const rows = (await this.pool.query(`SELECT id, language, canonical_number, title, source_url FROM reference_catalog_songs ${where} ORDER BY ${ORDER_BY_NATURAL_NUMBER} LIMIT $${pageValues.length - 1} OFFSET $${pageValues.length}`, pageValues)).rows as DatabaseRow[];
    return { records: rows.map(mapRecord), total, page, pageSize, pageCount, counts: await this.counts() };
  }

  async getById(id: string): Promise<ReferenceCatalogRecord | undefined> {
    const rows = (await this.pool.query("SELECT id, language, canonical_number, title, source_url FROM reference_catalog_songs WHERE id = $1", [id])).rows as DatabaseRow[];
    return rows[0] ? mapRecord(rows[0]) : undefined;
  }

  async counts(): Promise<ReferenceCatalogPage["counts"]> {
    const rows = await this.pool.query("SELECT count(*)::integer AS all, count(*) FILTER (WHERE language = 'czech')::integer AS czech, count(*) FILTER (WHERE language = 'polish')::integer AS polish FROM reference_catalog_songs");
    return { all: Number(rows.rows[0]?.all), czech: Number(rows.rows[0]?.czech), polish: Number(rows.rows[0]?.polish) };
  }
}

import type { Pool } from "pg";
import { referenceNumberParts } from "./reference-catalog-contract";
import type {
  ReferenceThematicLanguage,
  ReferenceThematicRange,
  ReferenceThematicSection,
  ReferenceThematicSectionProvider,
} from "./reference-thematic-section-contract";

type SectionRow = {
  id: string;
  theme_key: string;
  language: ReferenceThematicLanguage;
  title: string;
  parent_id: string;
  section_order: number;
  source_scan_page: number;
  source_printed_page: number;
};

type RangeRow = {
  section_id: string;
  range_order: number;
  from_number: number;
  to_number: number;
};

export class PostgresReferenceThematicSectionProvider implements ReferenceThematicSectionProvider {
  constructor(private readonly pool: Pool) {}

  async listSections(language: ReferenceThematicLanguage): Promise<ReferenceThematicSection[]> {
    assertLanguage(language);
    const rows = (await this.pool.query(
      `SELECT id,theme_key,language,title,parent_id,section_order,source_scan_page,source_printed_page
       FROM reference_thematic_sections
       WHERE language=$1
       ORDER BY section_order,id`,
      [language],
    )).rows as SectionRow[];
    return this.withRanges(rows);
  }

  async getSectionById(id: string): Promise<ReferenceThematicSection | undefined> {
    const row = (await this.pool.query(
      `SELECT id,theme_key,language,title,parent_id,section_order,source_scan_page,source_printed_page
       FROM reference_thematic_sections
       WHERE id=$1`,
      [id],
    )).rows[0] as SectionRow | undefined;
    if (!row) return undefined;
    return (await this.withRanges([row]))[0];
  }

  async resolveSection(
    language: ReferenceThematicLanguage,
    canonicalSongNumber: number,
  ): Promise<ReferenceThematicSection | undefined> {
    assertLanguage(language);
    const baseNumber = referenceNumberParts(canonicalSongNumber).base;
    const rows = (await this.pool.query(
      `SELECT DISTINCT s.id,s.theme_key,s.language,s.title,s.parent_id,s.section_order,s.source_scan_page,s.source_printed_page
       FROM reference_thematic_sections s
       JOIN reference_thematic_ranges r ON r.section_id=s.id
       WHERE s.language=$1 AND $2 BETWEEN r.from_number AND r.to_number
       ORDER BY s.section_order,s.id`,
      [language, baseNumber],
    )).rows as SectionRow[];
    if (rows.length > 1) throw new Error("Thematic-section resolution is ambiguous.");
    return rows[0] ? (await this.withRanges(rows))[0] : undefined;
  }

  private async withRanges(rows: SectionRow[]): Promise<ReferenceThematicSection[]> {
    if (!rows.length) return [];
    const ids = rows.map((row) => row.id);
    const ranges = (await this.pool.query(
      `SELECT section_id,range_order,from_number,to_number
       FROM reference_thematic_ranges
       WHERE section_id=ANY($1::text[])
       ORDER BY section_id,range_order`,
      [ids],
    )).rows as RangeRow[];
    const bySection = new Map<string, ReferenceThematicRange[]>();
    for (const range of ranges) {
      bySection.set(range.section_id, [
        ...(bySection.get(range.section_id) ?? []),
        { from: Number(range.from_number), to: Number(range.to_number) },
      ]);
    }
    return rows.map((row) => ({
      id: row.id,
      themeKey: row.theme_key,
      language: row.language,
      title: row.title,
      parentId: row.parent_id,
      order: Number(row.section_order),
      ranges: bySection.get(row.id) ?? [],
      sourcePage: {
        scanPage: Number(row.source_scan_page),
        printedPage: Number(row.source_printed_page),
      },
    }));
  }
}

function assertLanguage(value: unknown): asserts value is ReferenceThematicLanguage {
  if (value !== "czech" && value !== "polish") throw new Error("Thematic language is invalid.");
}

import { randomUUID } from "node:crypto";
import { hashPassword } from "better-auth/crypto";
import type { Pool, PoolClient } from "pg";
import { createOrganyAuth } from "../auth/server";
import { appendAuditEvent, humanAuditActor } from "./audit-history";
import { ProtectedActorError, resolveProtectedUser } from "./protected-actor";

const PROTECTED_ROLES = ["admin", "priest", "organist"] as const;
export type ProtectedRole = typeof PROTECTED_ROLES[number];
export type ProtectedAccountAdminRow = { authUserId: string; appUserId: string; username: string; displayName: string; active: boolean; roles: ProtectedRole[]; whatsappPhone?: string; personId?: string; personDisplayName?: string; personPriest?: boolean; personOrganist?: boolean };
export type ProtectedAccountProvisionTarget = { appUserId: string; displayName: string; currentRoles: string[]; personId?: string; personDisplayName?: string; personPriest?: boolean; personOrganist?: boolean };
export type ProtectedAccountAdminSnapshot = { accounts: ProtectedAccountAdminRow[]; eligibleActors: ProtectedAccountProvisionTarget[] };

export class ProtectedAccountAdminError extends Error {
  constructor(readonly code: "invalidInput" | "unauthenticated" | "permissionDenied" | "notFound" | "conflict", message: string) { super(message); this.name = "ProtectedAccountAdminError"; }
}

export class PostgresProtectedAccountAdminService {
  constructor(private readonly pool: Pool) {}

  async list(headers: Headers): Promise<ProtectedAccountAdminSnapshot> {
    await this.requireAdmin(headers);
    const [accounts, eligibleActors] = await Promise.all([
      this.pool.query(`
        select au.id auth_user_id, au.username, u.id app_user_id, u.display_name, u.active,
          l.whatsapp_phone_e164, u.person_id, p.display_name person_display_name, p.priest person_priest, p.organist person_organist,
          coalesce(array_agg(r.role order by r.role) filter (where r.role in ('admin','priest','organist')), '{}') protected_roles
        from protected_account_actor_links l
        join auth_users au on au.id = l.auth_user_id
        join app_users u on u.id = l.app_user_id
        left join app_user_roles r on r.user_id = u.id
        left join catalog_persons p on p.id = u.person_id
        group by au.id, u.id, p.id, l.whatsapp_phone_e164
        order by lower(u.display_name), lower(au.username)
      `),
      this.pool.query(`
        select u.id app_user_id, u.display_name, u.person_id,
          p.display_name person_display_name, p.priest person_priest, p.organist person_organist,
          coalesce(array_agg(r.role order by r.role) filter (where r.role is not null), '{}') roles
        from app_users u
        left join protected_account_actor_links l on l.app_user_id = u.id
        left join app_user_roles r on r.user_id = u.id
        left join catalog_persons p on p.id = u.person_id
        where u.active = true and l.app_user_id is null
          and u.id not like 'congregation-voter:%'
          and not exists (select 1 from preference_profiles pp where pp.user_id = u.id and pp.id like 'congregation-pref:%')
        group by u.id, p.id
        order by lower(u.display_name)
      `),
    ]);
    return {
      accounts: accounts.rows.map(mapAccount),
      eligibleActors: eligibleActors.rows.map((row) => ({
        appUserId: String(row.app_user_id), displayName: String(row.display_name), currentRoles: normalizeTextArray(row.roles),
        ...(row.person_id ? { personId: String(row.person_id) } : {}), ...(row.person_display_name ? { personDisplayName: String(row.person_display_name) } : {}),
        ...(row.person_id ? { personPriest: Boolean(row.person_priest), personOrganist: Boolean(row.person_organist) } : {}),
      })),
    };
  }

  async provision(headers: Headers, input: { appUserId?: unknown; username?: unknown; password?: unknown; roles?: unknown }) {
    await this.requireAdmin(headers);
    const appUserId = requireText(input.appUserId, "Application user is required.");
    const username = validateUsername(input.username);
    const password = validatePassword(input.password, "Initial password");
    const roles = validateProtectedRoles(input.roles, true);
    const client = await this.pool.connect();
    let createdAuthUserId: string | undefined;
    try {
      await client.query("begin");
      await serializeAdminMutation(client);
      const actor = await client.query(`
        select u.id, u.display_name, u.active,
          exists(select 1 from protected_account_actor_links l where l.app_user_id = u.id) linked,
          exists(select 1 from preference_profiles p where p.user_id = u.id and p.id like 'congregation-pref:%') nickname_profile
        from app_users u where u.id = $1 for update
      `, [appUserId]);
      const row = actor.rows[0];
      if (!row) throw new ProtectedAccountAdminError("notFound", "Application user was not found.");
      if (!Boolean(row.active)) throw new ProtectedAccountAdminError("conflict", "Only an active application user can receive a protected Account.");
      if (String(row.id).startsWith("congregation-voter:") || Boolean(row.nickname_profile)) throw new ProtectedAccountAdminError("permissionDenied", "Nickname-only congregation voters cannot receive protected Accounts.");
      if (Boolean(row.linked)) throw new ProtectedAccountAdminError("conflict", "This application user already has a protected Account.");
      if ((await client.query("select 1 from auth_users where username = $1 limit 1", [username])).rows[0]) throw new ProtectedAccountAdminError("conflict", "Username is already in use.");

      const provisioningAuth = createOrganyAuth({ allowSignUp: true });
      const result = await provisioningAuth.api.signUpEmail({ body: { email: `protected-${randomUUID()}@organy.invalid`, name: String(row.display_name), password, username } });
      createdAuthUserId = result.user.id;
      await client.query("delete from auth_sessions where user_id = $1", [createdAuthUserId]);
      await replaceProtectedRoles(client, appUserId, roles);
      await client.query("insert into protected_account_actor_links (auth_user_id, app_user_id) values ($1, $2)", [createdAuthUserId, appUserId]);
      await client.query("commit");
      return { account: await this.getAccount(appUserId), currentAdminLostAccess: false as const };
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      if (createdAuthUserId) await this.pool.query("delete from auth_users where id = $1", [createdAuthUserId]).catch(() => undefined);
      if (error instanceof ProtectedAccountAdminError) throw error;
      throw new ProtectedAccountAdminError("invalidInput", "Protected Account could not be provisioned.");
    } finally { client.release(); }
  }

  async updateRoles(headers: Headers, input: { appUserId?: unknown; roles?: unknown }) {
    const currentAdmin = await this.requireAdmin(headers);
    const appUserId = requireText(input.appUserId, "Application user is required.");
    const roles = validateProtectedRoles(input.roles, false);
    const client = await this.pool.connect();
    try {
      await client.query("begin");
      await serializeAdminMutation(client);
      const target = await requireLinkedTarget(client, appUserId);
      if (target.active && roles.length === 0) throw new ProtectedAccountAdminError("invalidInput", "An active protected Account must keep at least one protected role.");
      if (target.active && target.roles.includes("admin") && !roles.includes("admin")) await assertAnotherActiveAdmin(client, appUserId);
      await replaceProtectedRoles(client, appUserId, roles);
      await client.query("commit");
      return { account: await this.getAccount(appUserId), currentAdminLostAccess: currentAdmin.id === appUserId && !roles.includes("admin") };
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      throw normalizeAdminError(error);
    } finally { client.release(); }
  }

  async setActive(headers: Headers, input: { appUserId?: unknown; active?: unknown }) {
    const currentAdmin = await this.requireAdmin(headers);
    const appUserId = requireText(input.appUserId, "Application user is required.");
    if (typeof input.active !== "boolean") throw new ProtectedAccountAdminError("invalidInput", "Active state is required.");
    const active = input.active;
    const client = await this.pool.connect();
    try {
      await client.query("begin");
      await serializeAdminMutation(client);
      const target = await requireLinkedTarget(client, appUserId);
      if (active && target.roles.length === 0) throw new ProtectedAccountAdminError("invalidInput", "A protected Account needs at least one protected role before reactivation.");
      if (!active && target.active && target.roles.includes("admin")) await assertAnotherActiveAdmin(client, appUserId);
      await client.query("update app_users set active = $2, updated_at = now() where id = $1", [appUserId, active]);
      if (!active) await client.query("delete from auth_sessions where user_id = $1", [target.authUserId]);
      await client.query("commit");
      return { account: await this.getAccount(appUserId), currentAdminLostAccess: currentAdmin.id === appUserId && !active };
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      throw normalizeAdminError(error);
    } finally { client.release(); }
  }

  async resetPassword(headers: Headers, input: { appUserId?: unknown; password?: unknown }) {
    const currentAdmin = await this.requireAdmin(headers);
    const appUserId = requireText(input.appUserId, "Application user is required.");
    if (currentAdmin.id === appUserId) throw new ProtectedAccountAdminError("permissionDenied", "Use Change password to change your own password.");
    const password = validatePassword(input.password, "Replacement password");
    const client = await this.pool.connect();
    try {
      await client.query("begin");
      await serializeAdminMutation(client);
      const target = await requireLinkedTarget(client, appUserId);
      await replaceCredentialPasswordAndRevokeSessions(client, target.authUserId, password);
      await client.query("commit");
      return { account: await this.getAccount(appUserId), sessionsRevoked: true as const };
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      throw normalizeAdminError(error);
    } finally { client.release(); }
  }

  async removeWhatsappPhone(headers: Headers, input: { appUserId?: unknown }) {
    const currentAdmin = await this.requireAdmin(headers);
    const appUserId = requireText(input.appUserId, "Application user is required.");
    const client = await this.pool.connect();
    try {
      await client.query("begin");
      await serializeAdminMutation(client);
      await requireLinkedTarget(client, appUserId);
      const current = await client.query(
        "select whatsapp_phone_e164 from protected_account_actor_links where app_user_id = $1 for update",
        [appUserId],
      );
      if (!current.rows[0]) throw new ProtectedAccountAdminError("notFound", "Protected Account was not found.");
      const hadPhone = Boolean(current.rows[0].whatsapp_phone_e164);
      if (hadPhone) {
        await client.query(
          "update protected_account_actor_links set whatsapp_phone_e164 = null, whatsapp_phone_confirmed_at = null where app_user_id = $1",
          [appUserId],
        );
        await appendAuditEvent(client, {
          actor: humanAuditActor({
            userId: currentAdmin.id,
            displayName: currentAdmin.displayName,
            role: "admin",
            ...(currentAdmin.personId ? { personId: currentAdmin.personId } : {}),
          }),
          action: "account.whatsappPhone.adminForget",
          objectKind: "protectedAccount",
          objectRef: appUserId,
          beforeState: { configured: true },
          afterState: { configured: false },
        });
      }
      await client.query("commit");
      return { account: await this.getAccount(appUserId), removed: hadPhone };
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      throw normalizeAdminError(error);
    } finally { client.release(); }
  }

  async deleteAccount(headers: Headers, input: { appUserId?: unknown }) {
    const currentAdmin = await this.requireAdmin(headers);
    const appUserId = requireText(input.appUserId, "Application user is required.");
    if (currentAdmin.id === appUserId) throw new ProtectedAccountAdminError("permissionDenied", "Sign in as another admin before deleting your own protected Account.");
    const client = await this.pool.connect();
    try {
      await client.query("begin");
      await serializeAdminMutation(client);
      const target = await requireLinkedTarget(client, appUserId);
      if (target.active && target.roles.includes("admin")) await assertAnotherActiveAdmin(client, appUserId);
      await client.query("delete from auth_sessions where user_id = $1", [target.authUserId]);
      await client.query("delete from auth_users where id = $1", [target.authUserId]);
      await client.query("commit");
      return { appUserId, deletedAuthUserId: target.authUserId, currentAdminLostAccess: false as const };
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      throw normalizeAdminError(error);
    } finally { client.release(); }
  }

  async deletePerson(headers: Headers, input: { personId?: unknown }) {
    await this.requireAdmin(headers);
    const personId = requireText(input.personId, "Person is required.");
    const client = await this.pool.connect();
    try {
      await client.query("begin");
      await serializeAdminMutation(client);
      const person = await client.query("select id, display_name from catalog_persons where id = $1 for update", [personId]);
      if (!person.rows[0]) throw new ProtectedAccountAdminError("notFound", "Person was not found.");
      const serviceUse = await client.query("select 1 from service_contexts where priest_id = $1 or organist_id = $1 limit 1", [personId]);
      if (serviceUse.rows[0]) throw new ProtectedAccountAdminError("conflict", "Person is referenced by service history or an active plan. Deactivate the Person instead of deleting it.");
      const protectedUse = await client.query(`select 1 from app_users u join protected_account_actor_links l on l.app_user_id = u.id where u.person_id = $1 limit 1`, [personId]);
      if (protectedUse.rows[0]) throw new ProtectedAccountAdminError("conflict", "Delete the protected Account before deleting this Person.");
      await client.query("delete from app_users where person_id = $1", [personId]);
      await client.query("delete from catalog_persons where id = $1", [personId]);
      await client.query("commit");
      return { personId, displayName: String(person.rows[0].display_name), currentAdminLostAccess: false as const };
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      throw normalizeAdminError(error);
    } finally { client.release(); }
  }

  private async requireAdmin(headers: Headers) {
    try {
      const user = await resolveProtectedUser(headers, this.pool);
      if (!user.roles.includes("admin")) throw new ProtectedAccountAdminError("permissionDenied", "Admin role is required.");
      return user;
    } catch (error) {
      if (error instanceof ProtectedAccountAdminError) throw error;
      if (error instanceof ProtectedActorError) throw new ProtectedAccountAdminError(error.code === "unauthenticated" ? "unauthenticated" : "permissionDenied", error.message);
      throw error;
    }
  }

  private async getAccount(appUserId: string): Promise<ProtectedAccountAdminRow> {
    const result = await this.pool.query(`
      select au.id auth_user_id, au.username, u.id app_user_id, u.display_name, u.active,
        l.whatsapp_phone_e164, u.person_id, p.display_name person_display_name, p.priest person_priest, p.organist person_organist,
        coalesce(array_agg(r.role order by r.role) filter (where r.role in ('admin','priest','organist')), '{}') protected_roles
      from protected_account_actor_links l join auth_users au on au.id = l.auth_user_id join app_users u on u.id = l.app_user_id
      left join app_user_roles r on r.user_id = u.id left join catalog_persons p on p.id = u.person_id
      where u.id = $1 group by au.id, u.id, p.id, l.whatsapp_phone_e164
    `, [appUserId]);
    if (!result.rows[0]) throw new ProtectedAccountAdminError("notFound", "Protected Account was not found.");
    return mapAccount(result.rows[0]);
  }
}

export async function replaceCredentialPasswordAndRevokeSessions(client: PoolClient, authUserId: string, password: string) {
  const hashedPassword = await hashPassword(password);
  const updated = await client.query(
    "update auth_accounts set password = $2, updated_at = now() where user_id = $1 and provider_id = 'credential' and password is not null returning id",
    [authUserId, hashedPassword],
  );
  if (updated.rows.length !== 1) throw new ProtectedAccountAdminError("conflict", "Protected credential Account was not found.");
  await client.query("delete from auth_sessions where user_id = $1", [authUserId]);
}

async function serializeAdminMutation(client: PoolClient) { await client.query("select pg_advisory_xact_lock(hashtext('organy-protected-account-admin'))"); }
async function requireLinkedTarget(client: PoolClient, appUserId: string) {
  const result = await client.query(`
    select u.id, u.active, l.auth_user_id,
      coalesce((select array_agg(r.role order by r.role) from app_user_roles r where r.user_id = u.id and r.role in ('admin','priest','organist')), '{}') protected_roles
    from app_users u join protected_account_actor_links l on l.app_user_id = u.id
    where u.id = $1 for update of u
  `, [appUserId]);
  if (!result.rows[0]) throw new ProtectedAccountAdminError("notFound", "Protected Account was not found.");
  return { authUserId: String(result.rows[0].auth_user_id), active: Boolean(result.rows[0].active), roles: normalizeProtectedRoles(result.rows[0].protected_roles) };
}
async function assertAnotherActiveAdmin(client: PoolClient, excludedAppUserId: string) {
  const result = await client.query(`
    select count(distinct u.id)::integer n
    from protected_account_actor_links l
    join app_users u on u.id = l.app_user_id and u.active = true
    join app_user_roles r on r.user_id = u.id and r.role = 'admin'
    join auth_accounts aa on aa.user_id = l.auth_user_id and aa.provider_id = 'credential' and aa.password is not null
    where u.id <> $1
  `, [excludedAppUserId]);
  if (Number(result.rows[0]?.n ?? 0) < 1) throw new ProtectedAccountAdminError("conflict", "The last active protected admin cannot lose admin access.");
}
async function replaceProtectedRoles(client: PoolClient, appUserId: string, roles: ProtectedRole[]) {
  await client.query("delete from app_user_roles where user_id = $1 and role in ('admin','priest','organist')", [appUserId]);
  for (const role of roles) await client.query("insert into app_user_roles (user_id, role) values ($1, $2) on conflict do nothing", [appUserId, role]);
}
function mapAccount(row: Record<string, unknown>): ProtectedAccountAdminRow { return { authUserId: String(row.auth_user_id), appUserId: String(row.app_user_id), username: String(row.username), displayName: String(row.display_name), active: Boolean(row.active), roles: normalizeProtectedRoles(row.protected_roles), ...(row.whatsapp_phone_e164 ? { whatsappPhone: String(row.whatsapp_phone_e164) } : {}), ...(row.person_id ? { personId: String(row.person_id) } : {}), ...(row.person_display_name ? { personDisplayName: String(row.person_display_name) } : {}), ...(row.person_id ? { personPriest: Boolean(row.person_priest), personOrganist: Boolean(row.person_organist) } : {}) }; }
function validateUsername(value: unknown): string { const username = requireText(value, "Username is required.").toLowerCase(); if (username.length < 3 || username.length > 64 || !/^[a-z0-9._-]+$/.test(username)) throw new ProtectedAccountAdminError("invalidInput", "Username must be 3-64 characters using letters, numbers, dot, underscore, or hyphen."); return username; }
function validatePassword(value: unknown, label: string): string { if (typeof value !== "string" || value.length < 8 || value.length > 128) throw new ProtectedAccountAdminError("invalidInput", `${label} must contain 8-128 characters.`); return value; }
function validateProtectedRoles(value: unknown, requireAtLeastOne: boolean): ProtectedRole[] { if (!Array.isArray(value)) throw new ProtectedAccountAdminError("invalidInput", "Protected roles are required."); const roles = [...new Set(value.map(String))]; if (roles.some((role) => !PROTECTED_ROLES.includes(role as ProtectedRole))) throw new ProtectedAccountAdminError("invalidInput", "Protected roles may contain only admin, priest, or organist."); if (requireAtLeastOne && roles.length === 0) throw new ProtectedAccountAdminError("invalidInput", "At least one protected role is required."); return roles as ProtectedRole[]; }
function normalizeProtectedRoles(value: unknown): ProtectedRole[] { return normalizeTextArray(value).filter((role): role is ProtectedRole => PROTECTED_ROLES.includes(role as ProtectedRole)); }
function normalizeTextArray(value: unknown): string[] { if (Array.isArray(value)) return value.map(String); if (typeof value === "string") return value.replace(/[{}]/g, "").split(",").filter(Boolean); return []; }
function requireText(value: unknown, message: string): string { if (typeof value !== "string" || !value.trim()) throw new ProtectedAccountAdminError("invalidInput", message); return value.trim(); }
function normalizeAdminError(error: unknown): ProtectedAccountAdminError { if (error instanceof ProtectedAccountAdminError) return error; return new ProtectedAccountAdminError("conflict", error instanceof Error ? error.message : "Protected Account administration failed."); }

import type { Pool } from "pg";
import type { ActorIdentity, AppUser } from "./interaction-contracts";
import type { PlanningRole } from "../planning-lifecycle";
import { LocalActorError, parseLocalActorContext, PostgresLocalActorResolver, type LocalActorContext } from "./local-actor";
import { assertProtectedAuthConfigured, auth } from "../auth/server";

const ROLE_ORDER: PlanningRole[] = ["priest", "organist", "admin", "congregationMember"];

type ProtectedActorAcceptanceResolver = (
  headers: Headers,
  pool: Pick<Pool, "query">,
  requestedContext?: unknown,
) => Promise<ActorIdentity>;
let acceptanceResolver: ProtectedActorAcceptanceResolver | undefined;

export class ProtectedActorError extends Error {
  constructor(
    public readonly code: "unauthenticated" | "invalidInput" | "permissionDenied",
    message: string,
  ) {
    super(message);
  }
}

/**
 * Narrow in-process acceptance seam for pre-auth route regression tests.
 * Production never installs this override; the default path below always uses Better Auth session state.
 */
export function useProtectedActorForAcceptance(resolver: ProtectedActorAcceptanceResolver): () => void {
  const previous = acceptanceResolver;
  acceptanceResolver = resolver;
  return () => { acceptanceResolver = previous; };
}

/**
 * Compatibility adapter used only by historical route acceptance tests that predate protected sessions.
 * It preserves their actor/role business assertions without restoring client-selected identity in production.
 */
export function useLocalActorSimulatorForAcceptance(defaultContext?: LocalActorContext): () => void {
  return useProtectedActorForAcceptance(async (_headers, pool, requestedContext) => {
    try {
      const context = requestedContext === undefined && defaultContext
        ? defaultContext
        : parseLocalActorContext(requestedContext);
      return await new PostgresLocalActorResolver(pool).resolve(context);
    } catch (error) {
      if (error instanceof LocalActorError) throw new ProtectedActorError(error.code, error.message);
      throw error;
    }
  });
}

export async function resolveProtectedUser(headers: Headers, pool: Pick<Pool, "query">): Promise<AppUser> {
  assertProtectedAuthConfigured();
  const session = await auth.api.getSession({ headers });
  if (!session?.user?.id) throw new ProtectedActorError("unauthenticated", "Sign in is required.");

  const { rows } = await pool.query(`
    select u.id, u.display_name, u.person_id, u.active, l.whatsapp_phone_e164,
      coalesce(array_agg(r.role order by r.role) filter (where r.role is not null), '{}') roles
    from protected_account_actor_links l
    join app_users u on u.id = l.app_user_id
    left join app_user_roles r on r.user_id = u.id
    where l.auth_user_id = $1
    group by u.id, l.whatsapp_phone_e164
  `, [session.user.id]);

  if (!rows[0]) throw new ProtectedActorError("permissionDenied", "The authenticated account is not linked to an application user.");
  const user = mapUser(rows[0]);
  if (!user.active) throw new ProtectedActorError("permissionDenied", "The authenticated application user is inactive.");
  if (user.roles.length === 0) throw new ProtectedActorError("permissionDenied", "The authenticated application user has no assigned role.");
  if (!user.roles.some((role) => role === "admin" || role === "priest" || role === "organist")) {
    throw new ProtectedActorError("permissionDenied", "This account has no protected staff role.");
  }
  return user;
}

export async function resolveProtectedActor(
  headers: Headers,
  pool: Pick<Pool, "query">,
  requestedContext?: unknown,
): Promise<ActorIdentity> {
  if (acceptanceResolver) return acceptanceResolver(headers, pool, requestedContext);

  const user = await resolveProtectedUser(headers, pool);
  const requestedRole = parseRequestedRole(requestedContext);
  if (requestedRole && !user.roles.includes(requestedRole)) {
    throw new ProtectedActorError("permissionDenied", "The requested role is not assigned to the authenticated user.");
  }
  const role = requestedRole ?? ROLE_ORDER.find((candidate) => user.roles.includes(candidate));
  if (!role) throw new ProtectedActorError("permissionDenied", "The authenticated user has no usable protected role.");
  return {
    userId: user.id,
    displayName: user.displayName,
    role,
    ...(user.personId ? { personId: user.personId } : {}),
  };
}

function parseRequestedRole(value: unknown): PlanningRole | undefined {
  if (value === undefined) return undefined;
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new ProtectedActorError("invalidInput", "Protected actor context is malformed.");
  }
  const record = value as Record<string, unknown>;
  const keys = Object.keys(record);
  if (keys.some((key) => key !== "role")) {
    throw new ProtectedActorError("invalidInput", "Client-supplied user identity is not accepted for protected operations.");
  }
  if (record.role === undefined) return undefined;
  if (typeof record.role !== "string" || !ROLE_ORDER.includes(record.role as PlanningRole)) {
    throw new ProtectedActorError("invalidInput", "Requested protected role is malformed.");
  }
  return record.role as PlanningRole;
}

function mapUser(row: Record<string, unknown>): AppUser {
  return {
    id: String(row.id),
    displayName: String(row.display_name),
    ...(row.person_id ? { personId: String(row.person_id) } : {}),
    active: Boolean(row.active),
    ...(row.whatsapp_phone_e164 ? { whatsappPhone: String(row.whatsapp_phone_e164) } : {}),
    roles: normalizeRoles(row.roles).sort((a, b) => ROLE_ORDER.indexOf(a) - ROLE_ORDER.indexOf(b)),
  };
}

function normalizeRoles(value: unknown): PlanningRole[] {
  const roles = Array.isArray(value)
    ? value.map(String)
    : typeof value === "string"
      ? value.replace(/[{}]/g, "").split(",").filter(Boolean)
      : [];
  return roles.map((role) => role === "congregation_member" ? "congregationMember" : role as PlanningRole);
}

import { randomUUID } from "node:crypto";
import type { Pool, PoolClient } from "pg";
import { createOrganyAuth } from "../auth/server";
import { ProtectedActorError, resolveProtectedUser } from "./protected-actor";
import { ProtectedAccountAdminError } from "./protected-account-admin";

export type StaffRole = "priest" | "organist";
export type ProtectedStaffOnboardingInput = {
  personId?: unknown;
  displayName?: unknown;
  username?: unknown;
  password?: unknown;
  roles?: unknown;
};

export class PostgresProtectedStaffOnboardingService {
  constructor(private readonly pool: Pool) {}

  async create(headers: Headers, input: ProtectedStaffOnboardingInput) {
    await this.requireAdmin(headers);
    const roles = validateRoles(input.roles);
    const username = validateUsername(input.username);
    const password = validatePassword(input.password);
    const requestedPersonId = optionalText(input.personId);
    const displayName = optionalText(input.displayName);
    if (!requestedPersonId && !displayName) throw new ProtectedAccountAdminError("invalidInput", "Display name is required for new staff.");

    const client = await this.pool.connect();
    let createdAuthUserId: string | undefined;
    try {
      await client.query("begin");
      await client.query("select pg_advisory_xact_lock(hashtext('organy-protected-staff-onboarding'))");
      if ((await client.query("select 1 from auth_users where username = $1 limit 1", [username])).rows[0]) {
        throw new ProtectedAccountAdminError("conflict", "Username is already in use.");
      }

      const person = requestedPersonId
        ? await lockExistingPerson(client, requestedPersonId)
        : await createPerson(client, displayName!, roles);
      if (!person.active) throw new ProtectedAccountAdminError("conflict", "Only an active Person can receive a protected Account.");

      if (roles.includes("priest") && !person.priest) await client.query("update catalog_persons set priest = true, updated_at = now() where id = $1", [person.id]);
      if (roles.includes("organist") && !person.organist) await client.query("update catalog_persons set organist = true, updated_at = now() where id = $1", [person.id]);

      const linked = await client.query("select u.id from app_users u where u.person_id = $1 and u.active = true limit 1", [person.id]);
      let appUserId: string;
      if (linked.rows[0]) {
        appUserId = String(linked.rows[0].id);
        if ((await client.query("select 1 from protected_account_actor_links where app_user_id = $1", [appUserId])).rows[0]) {
          throw new ProtectedAccountAdminError("conflict", "This Person already has a protected Account.");
        }
        await client.query("update app_users set display_name = $2, updated_at = now() where id = $1", [appUserId, person.displayName]);
      } else {
        appUserId = `staff:${randomUUID()}`;
        await client.query(
          "insert into app_users (id, display_name, person_id, active, created_at, updated_at) values ($1, $2, $3, true, now(), now())",
          [appUserId, person.displayName, person.id],
        );
      }

      await client.query("delete from app_user_roles where user_id = $1 and role in ('priest','organist')", [appUserId]);
      for (const role of roles) await client.query("insert into app_user_roles (user_id, role) values ($1, $2) on conflict do nothing", [appUserId, role]);

      const provisioningAuth = createOrganyAuth({ allowSignUp: true });
      const result = await provisioningAuth.api.signUpEmail({ body: {
        email: `protected-${randomUUID()}@organy.invalid`,
        name: person.displayName,
        password,
        username,
      } });
      createdAuthUserId = result.user.id;
      await client.query("delete from auth_sessions where user_id = $1", [createdAuthUserId]);
      await client.query("insert into protected_account_actor_links (auth_user_id, app_user_id) values ($1, $2)", [createdAuthUserId, appUserId]);
      await client.query("commit");
      return { personId: person.id, appUserId, username, roles };
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      if (createdAuthUserId) await this.pool.query("delete from auth_users where id = $1", [createdAuthUserId]).catch(() => undefined);
      if (error instanceof ProtectedAccountAdminError) throw error;
      throw new ProtectedAccountAdminError("invalidInput", "Protected staff Account could not be created.");
    } finally {
      client.release();
    }
  }

  private async requireAdmin(headers: Headers) {
    try {
      const user = await resolveProtectedUser(headers, this.pool);
      if (!user.roles.includes("admin")) throw new ProtectedAccountAdminError("permissionDenied", "Admin role is required.");
      return user;
    } catch (error) {
      if (error instanceof ProtectedAccountAdminError) throw error;
      if (error instanceof ProtectedActorError) throw new ProtectedAccountAdminError(error.code === "unauthenticated" ? "unauthenticated" : "permissionDenied", error.message);
      throw error;
    }
  }
}

async function lockExistingPerson(client: PoolClient, personId: string) {
  const result = await client.query("select id, display_name, active, priest, organist from catalog_persons where id = $1 for update", [personId]);
  const row = result.rows[0];
  if (!row) throw new ProtectedAccountAdminError("notFound", "Selected Person was not found.");
  return { id: String(row.id), displayName: String(row.display_name), active: Boolean(row.active), priest: Boolean(row.priest), organist: Boolean(row.organist) };
}

async function createPerson(client: PoolClient, displayName: string, roles: StaffRole[]) {
  const id = `staff-person:${randomUUID()}`;
  await client.query(
    "insert into catalog_persons (id, display_name, active, priest, organist, created_at, updated_at) values ($1, $2, true, $3, $4, now(), now())",
    [id, displayName, roles.includes("priest"), roles.includes("organist")],
  );
  return { id, displayName, active: true, priest: roles.includes("priest"), organist: roles.includes("organist") };
}

function validateRoles(value: unknown): StaffRole[] {
  if (!Array.isArray(value)) throw new ProtectedAccountAdminError("invalidInput", "Staff roles are required.");
  const roles = [...new Set(value.map(String))];
  if (roles.length === 0 || roles.some((role) => role !== "priest" && role !== "organist")) {
    throw new ProtectedAccountAdminError("invalidInput", "Choose priest, organist, or both.");
  }
  return roles as StaffRole[];
}
function validateUsername(value: unknown) {
  const username = requireText(value, "Username is required.").toLowerCase();
  if (username.length < 3 || username.length > 64 || !/^[a-z0-9._-]+$/.test(username)) throw new ProtectedAccountAdminError("invalidInput", "Username must be 3-64 characters using letters, numbers, dot, underscore, or hyphen.");
  return username;
}
function validatePassword(value: unknown) {
  if (typeof value !== "string" || value.length < 8 || value.length > 128) throw new ProtectedAccountAdminError("invalidInput", "Initial password must contain 8-128 characters.");
  return value;
}
function requireText(value: unknown, message: string) {
  if (typeof value !== "string" || !value.trim()) throw new ProtectedAccountAdminError("invalidInput", message);
  return value.trim();
}
function optionalText(value: unknown) { return typeof value === "string" && value.trim() ? value.trim() : undefined; }

import type { Pool } from "pg";
import type { PlanningRole } from "../planning-lifecycle";
import type { AppUser } from "./interaction-contracts";
import { appendAuditEvent, humanAuditActor } from "./audit-history";
import { canOwnWhatsAppPhone, normalizeWhatsAppPhone } from "./whatsapp-phone";

export type ProtectedWhatsAppPhoneSetting = {
  phoneE164: string | null;
  confirmedAt: string | null;
};

export class ProtectedWhatsAppPhoneError extends Error {
  constructor(readonly code: "invalidInput" | "permissionDenied" | "notFound", message: string) {
    super(message);
    this.name = "ProtectedWhatsAppPhoneError";
  }
}

export class PostgresProtectedWhatsAppPhoneService {
  constructor(private readonly pool: Pool) {}

  async get(user: AppUser): Promise<ProtectedWhatsAppPhoneSetting> {
    assertEligibleOwner(user);
    const result = await this.pool.query(
      `select whatsapp_phone_e164, whatsapp_phone_confirmed_at
         from protected_account_actor_links
        where app_user_id = $1`,
      [user.id],
    );
    if (!result.rows[0]) throw new ProtectedWhatsAppPhoneError("notFound", "Protected Account was not found.");
    return mapSetting(result.rows[0]);
  }

  async save(user: AppUser, requestedRole: PlanningRole, input: unknown): Promise<ProtectedWhatsAppPhoneSetting> {
    assertEligibleOwner(user);
    const role = resolvePhoneAuditRole(user, requestedRole);
    let phoneE164: string;
    try { phoneE164 = normalizeWhatsAppPhone(input); }
    catch (error) {
      throw new ProtectedWhatsAppPhoneError("invalidInput", error instanceof Error ? error.message : "Phone number is invalid.");
    }

    const client = await this.pool.connect();
    try {
      await client.query("begin");
      const current = await client.query(
        `select whatsapp_phone_e164, whatsapp_phone_confirmed_at
           from protected_account_actor_links
          where app_user_id = $1
          for update`,
        [user.id],
      );
      if (!current.rows[0]) throw new ProtectedWhatsAppPhoneError("notFound", "Protected Account was not found.");
      const before = mapSetting(current.rows[0]);
      const updated = await client.query(
        `update protected_account_actor_links
            set whatsapp_phone_e164 = $2, whatsapp_phone_confirmed_at = now()
          where app_user_id = $1
          returning whatsapp_phone_e164, whatsapp_phone_confirmed_at`,
        [user.id, phoneE164],
      );
      const after = mapSetting(updated.rows[0]);
      await appendAuditEvent(client, {
        actor: humanAuditActor({ userId: user.id, displayName: user.displayName, role, ...(user.personId ? { personId: user.personId } : {}) }),
        action: before.phoneE164 ? "account.whatsappPhone.update" : "account.whatsappPhone.save",
        objectKind: "protectedAccount",
        objectRef: user.id,
        beforeState: { configured: Boolean(before.phoneE164) },
        afterState: { configured: true },
      });
      await client.query("commit");
      return after;
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      if (error instanceof ProtectedWhatsAppPhoneError) throw error;
      throw new ProtectedWhatsAppPhoneError("invalidInput", "WhatsApp phone could not be saved.");
    } finally { client.release(); }
  }

  async forget(user: AppUser, requestedRole: PlanningRole): Promise<ProtectedWhatsAppPhoneSetting> {
    assertEligibleOwner(user);
    const role = resolvePhoneAuditRole(user, requestedRole);
    const client = await this.pool.connect();
    try {
      await client.query("begin");
      const current = await client.query(
        `select whatsapp_phone_e164, whatsapp_phone_confirmed_at
           from protected_account_actor_links
          where app_user_id = $1
          for update`,
        [user.id],
      );
      if (!current.rows[0]) throw new ProtectedWhatsAppPhoneError("notFound", "Protected Account was not found.");
      const before = mapSetting(current.rows[0]);
      if (before.phoneE164) {
        await client.query(
          `update protected_account_actor_links
              set whatsapp_phone_e164 = null, whatsapp_phone_confirmed_at = null
            where app_user_id = $1`,
          [user.id],
        );
        await appendAuditEvent(client, {
          actor: humanAuditActor({ userId: user.id, displayName: user.displayName, role, ...(user.personId ? { personId: user.personId } : {}) }),
          action: "account.whatsappPhone.forget",
          objectKind: "protectedAccount",
          objectRef: user.id,
          beforeState: { configured: true },
          afterState: { configured: false },
        });
      }
      await client.query("commit");
      return { phoneE164: null, confirmedAt: null };
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      if (error instanceof ProtectedWhatsAppPhoneError) throw error;
      throw new ProtectedWhatsAppPhoneError("invalidInput", "WhatsApp phone could not be forgotten.");
    } finally { client.release(); }
  }
}

export function resolvePhoneAuditRole(user: AppUser, requestedRole: PlanningRole): "priest" | "admin" {
  if ((requestedRole === "priest" || requestedRole === "admin") && user.roles.includes(requestedRole)) return requestedRole;
  if (user.roles.includes("priest")) return "priest";
  if (user.roles.includes("admin")) return "admin";
  throw new ProtectedWhatsAppPhoneError("permissionDenied", "Only priest or admin protected Accounts can use WhatsApp phone settings.");
}

function assertEligibleOwner(user: AppUser) {
  if (!canOwnWhatsAppPhone(user.roles)) {
    throw new ProtectedWhatsAppPhoneError("permissionDenied", "Only priest or admin protected Accounts can use WhatsApp phone settings.");
  }
}

function mapSetting(row: Record<string, unknown>): ProtectedWhatsAppPhoneSetting {
  return {
    phoneE164: row.whatsapp_phone_e164 ? String(row.whatsapp_phone_e164) : null,
    confirmedAt: row.whatsapp_phone_confirmed_at
      ? new Date(String(row.whatsapp_phone_confirmed_at)).toISOString()
      : null,
  };
}
